let MOCK=(()=>{try{const x=JSON.parse(localStorage.getItem(dataKey()));if(!x)return structuredClone(DEFAULT_MOCK);const base=structuredClone(DEFAULT_MOCK);Object.keys(x).forEach(k=>{base[k]=x[k]});Object.keys(base).forEach(k=>{if(x[k]===undefined)base[k]=structuredClone(DEFAULT_MOCK[k])});if(!Array.isArray(base.agencies))base.agencies=structuredClone(DEFAULT_MOCK.agencies);if(!Array.isArray(base.users))base.users=structuredClone(DEFAULT_MOCK.users);base.templates=structuredClone(TEMPLATES);base.websites=(Array.isArray(base.websites)?base.websites:[]).filter(x=>{const p=x.payload||{};return p.multi_page===true || p.single_page===true || p.template_id || !Array.isArray(p.pages) || p.pages.length<=1});return base}catch(e){return structuredClone(DEFAULT_MOCK)}})();
