function login(){try{const email=String($('email').value||'').trim().toLowerCase();const password=String($('password').value||'');const mode=String($('loginMode')?.value||'main');if(!email||!password){alert('Email and password required');return;}if(mode==='training' && email!=='training@apexjov.test'){alert('Training Portal uses the dedicated training login.');return;}if(mode==='main' && email==='training@apexjov.test'){alert('Select Training Portal as the environment.');return;}if(mode==='training' && password!=='training123'){alert('Invalid Training Portal password.');return;}TRAINING_MODE=mode==='training';try{localStorage.setItem('apex_active_mode',TRAINING_MODE?'training':'main')}catch(e){}const u=DEMO_USERS[email]||MOCK.users.find(x=>String(x.email||'').toLowerCase()===email);if(u&&u.password===password){me={email:email,...u,agency_id:u.agency_id||1,customer_id:u.customer_id||null};token=(TRAINING_MODE?'training-':'offline-')+email;try{localStorage.setItem(TRAINING_MODE?'apex_training_token':'apex_final_token',token)}catch(e){}$('login').classList.add('hide');$('app').classList.remove('hide');$('who').textContent=me.name+' • '+(TRAINING_MODE?'Training Portal':'Main Testing');$('modeBanner').style.display=TRAINING_MODE?'block':'none';applyTenantBranding();buildNav();openPage('dashboard');return;}alert('Invalid login. Check email/password.');}catch(e){alert('Login error: '+e.message)}}
function boot(){try{if(!token)return;const isTraining=token.indexOf('training-')===0;TRAINING_MODE=isTraining;const em=token.slice(isTraining?9:8);const u=DEMO_USERS[em]||MOCK.users.find(x=>String(x.email||'').toLowerCase()===em);if(u){me={email:em,...u,agency_id:u.agency_id||1,customer_id:u.customer_id||null};$('login').classList.add('hide');$('app').classList.remove('hide');$('who').textContent=me.name+' • '+(TRAINING_MODE?'Training Portal':'Main Testing');$('modeBanner').style.display=TRAINING_MODE?'block':'none';applyTenantBranding();buildNav();openPage('dashboard');return;}}catch(e){try{localStorage.removeItem(TRAINING_MODE?'apex_training_token':'apex_final_token')}catch(_){} }}
function logout(){try{localStorage.removeItem(TRAINING_MODE?'apex_training_token':'apex_final_token');localStorage.setItem('apex_active_mode',TRAINING_MODE?'training':'main')}catch(e){};location.reload()}
function applyTenantBranding(){try{const ag=(MOCK.agencies||[]).find(a=>Number(a.id)===Number(me.agency_id||1));const brand=document.querySelector('.app-head .brand');if(!brand||me.role==='platform_owner')return;const name=ag?.brand_name||ag?.name;if(name)brand.textContent=name;if(ag?.logo_url){brand.innerHTML=`<img src="${esc(ag.logo_url)}" alt="Agency logo" style="max-width:150px;max-height:38px;object-fit:contain"> <span>${esc(name||'')}</span>`}}catch(e){}}function buildNav(){const role=me.role||me.user?.role;const groups=[['MAIN',[['dashboard','🏠 Dashboard'],['customers','👥 Customers'],['pipelines','📊 Pipelines']]],['LEADS & CRM',[['crm','🎯 Lead Management'],['lead_automation','⚡ Lead Automation'],['forms','📝 Forms'],['funnels','🔗 Funnels']]],['SALES & OPERATIONS',[['sales','💼 Sales'],['operations','⚙ Operations'],['inbox','📥 Inbox'],['calendar','📅 Calendar'],['tasks','✅ Tasks']]],['MARKETING',[['campaigns','📣 Campaigns'],['meta_ads','📈 Meta Ads'],['google_ads','📊 Google Ads'],['whatsapp','💬 WhatsApp'],['websites','🌐 Websites'],['templates','📚 Templates']]],['FINANCE & REPORTS',[['payments','💳 Finance / Billing'],['reports','📊 Reports']]],['TOOLS',[['domains','🔗 Domains'],['seo','🔎 SEO'],['referrals','🤝 Referrals / Reviews'],['chatbot','🤖 Chatbot'],['notifications','🔔 Notifications']]],['AGENCY MANAGEMENT',[['agencies','🏢 Agencies / Tenants']]],['ADMIN',[['settings','⚙ Settings'],['audit','🛡 Audit Logs'],['training_reset','🧪 Reset Training Data']]]];$('nav').innerHTML=groups.map(g=>{const items=g[1].filter(x=>{if(x[0]==='agencies'&&role!=='platform_owner')return false;if(x[0]==='training_reset'&&!TRAINING_MODE)return false;return me.permissions.includes('*')||me.permissions.includes(x[0])||((x[0]==='settings'||x[0]==='audit')&&['platform_owner','agency_admin'].includes(role))});return items.length?`<div class="nav-group"><div class="nav-label">${g[0]}</div>${items.map(x=>`<button class="nav-btn" data-k="${x[0]}" onclick="openPage('${x[0]}')">${x[1]}</button>`).join('')}</div>`:''}).join('')}function toggleNav(){document.getElementById('nav')?.classList.toggle('open')}function setActive(k){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('on',b.dataset.k===k))}
async function openPage(k){setActive(k);const p=$('panel');p.innerHTML='<div class="card">Loading…</div>';try{if(k==='dashboard')return dashboard();if(k==='customers')return customers();if(k==='templates')return templates();if(k==='crm')return crm();if(k==='pipelines')return pipelines();if(k==='forms')return forms();if(k==='funnels')return funnels();if(k==='campaigns')return recordsPage('Campaigns','/campaigns',true);if(k==='lead_automation')return moduleManager('Lead Automation','lead_automation',['Rule name','Trigger','Action','Status']);if(k==='sales')return moduleManager('Sales','sales',['Opportunity','Customer','Value','Stage','Expected Close']);if(k==='operations')return moduleManager('Operations','operations',['Task/Operation','Owner','Due Date','Status']);if(k==='inbox')return moduleManager('Inbox','inbox',['Contact','Channel','Subject','Status']);if(k==='calendar')return moduleManager('Calendar','calendar',['Title','Date','Time','Customer','Status']);if(k==='tasks')return moduleManager('Tasks','tasks',['Task','Owner','Due Date','Priority','Status']);if(k==='meta_ads')return meta();if(k==='google_ads')return googleAds();if(k==='whatsapp')return whatsapp();if(k==='websites')return websites();if(k==='domains')return domains();if(k==='seo')return seo();if(k==='payments')return billing();if(k==='referrals')return recordsPage('Referrals / Reviews','/referrals');if(k==='notifications')return recordsPage('Notifications','/notifications');if(k==='agencies')return agencies();if(k==='settings')return settings();if(k==='reports')return reports();if(k==='audit')return audit();if(k==='training_reset')return trainingResetPage()}catch(e){p.innerHTML=`<div class="card danger">${e.message}</div>`}}
function trainingResetPage(){if(!TRAINING_MODE){$('panel').innerHTML='<div class="card danger">Training Portal only.</div>';return;}$('panel').innerHTML=`<div class="card hero-card"><h2>🧪 Training Environment</h2><p class="muted">This environment is completely separate from the Main Testing Portal. Create dummy customers, forms, pipelines, funnels and leads here without changing the main testing data.</p><div class="row"><button class="btn primary" onclick="resetTraining()">Reset Training Data</button><span class="badge">Main data protected</span></div></div>`}
async function dashboard(){const r=await api('/reports/summary');const agencyCount=me.role==='platform_owner'?(await api('/agencies')).length:null;$('panel').innerHTML=`<div class="grid">${me.role==='platform_owner'?`<div class="card"><div class="muted">Agencies / Tenants</div><div class="stats">${agencyCount}</div></div>`:''}<div class="card"><div class="muted">Customers</div><div class="stats">${r.customers}</div></div><div class="card"><div class="muted">Leads</div><div class="stats">${r.leads}</div></div><div class="card"><div class="muted">Paid Revenue</div><div class="stats">₹${Number(r.paid_revenue).toLocaleString('en-IN')}</div></div><div class="card"><div class="muted">Pipelines</div><div class="stats">${r.pipelines||0}</div></div><div class="card"><div class="muted">Forms</div><div class="stats">${r.forms||0}</div></div><div class="card"><div class="muted">Funnels</div><div class="stats">${r.funnels||0}</div></div><div class="card"><div class="muted">Websites</div><div class="stats">${r.websites||0}</div></div><div class="card"><div class="muted">Environment</div><div class="stats">STAGING</div></div></div><br><div class="card"><h3>System status</h3><p class="ok">✓ Authentication & RBAC</p><p class="ok">✓ Tenant/customer scoping</p><p class="ok">✓ CRM + Form submission flow</p><p class="ok">✓ Billing lifecycle + mock checkout</p><p class="ok">✓ Website publish + SEO foundation</p><p class="warn">• Live provider credentials are intentionally not connected in staging</p></div>`}
function modal(title,html){$('mtitle').textContent=title;$('mbody').innerHTML=html;$('modal').classList.add('show')}function closeModal(){$('modal').classList.remove('show')}function formField(label,id,placeholder=''){return `<label class="muted">${label}</label><input class="input" id="f_${id}" placeholder="${placeholder}">`}

function formatDateIN(v){if(!v)return '—';const s=String(v).trim();let m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return `${m[3]}/${m[2]}/${m[1]}`;m=s.match(/^(\d{2})[\/-](\d{2})[\/-](\d{4})$/);if(m)return `${m[1]}/${m[2]}/${m[3]}`;const d=new Date(s);return Number.isNaN(d.getTime())?s:d.toLocaleDateString('en-GB',{day:'2-digit',month:'2-digit',year:'numeric'});}
function dateInputISO(v){if(!v)return '';const s=String(v).trim();let m=s.match(/^(\d{2})[\/-](\d{2})[\/-](\d{4})$/);if(m)return `${m[3]}-${m[2]}-${m[1]}`;m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/);if(m)return s;return s;}
function validDateIN(v){if(!v)return true;const s=String(v).trim();const m=s.match(/^(\d{2})[\/](\d{2})[\/](\d{4})$/);if(!m)return false;const d=new Date(Number(m[3]),Number(m[2])-1,Number(m[1]));return d.getFullYear()===Number(m[3])&&d.getMonth()===Number(m[2])-1&&d.getDate()===Number(m[1]);}
async function customers(){const d=await api('/customers');$('panel').innerHTML=`<div class="card"><div class="row"><h3 style="margin-right:auto">Customers</h3>${me.role!=='customer'?'<button class="btn primary" onclick="newCustomer()">+ Add Customer</button><button class="btn" onclick="openPage("pipelines")">📊 Pipelines</button>':''}</div><p class="muted">Business profile, billing/GST details and service status. Only essential customer information is collected.</p><div class="grid">${d.map(x=>`<div class="card"><div class="row"><h3 style="margin-right:auto">${esc(x.business_name||x.name)}</h3><span class="badge">${esc(x.status||'Active')}</span></div><div class="row" style="gap:12px;align-items:center">${x.logo_url?`<img src="${esc(x.logo_url)}" style="width:52px;height:52px;object-fit:contain;border-radius:10px;border:1px solid #ddd;background:#fff">`:''}${x.owner_photo_url?`<img src="${esc(x.owner_photo_url)}" style="width:52px;height:52px;object-fit:cover;border-radius:50%;border:1px solid #ddd">`:''}<div class="muted">${esc(x.name)} • ${esc(x.email)} • ${esc(x.phone||'')}</div></div><p>Industry: <b>${esc(x.industry||'—')}</b><br>Plan: <b>${esc(x.plan||'Custom')}</b><br>GST: <b>${esc(x.gst_status||'Not Registered')}</b>${x.gstin?` • ${esc(x.gstin)}`:''}</p><div class="row">${me.role!=='customer'?`<button class="btn" onclick="editCustomer(${x.id})">Edit Profile</button><button class="btn" onclick="toggleCustomer(${x.id},'${x.status==='Active'?'Suspended':'Active'}')">${x.status==='Active'?'Suspend':'Activate'}</button>`:''}</div></div>`).join('')||'<div class="card">No customers</div>'}</div></div>`}
function imageUploadField(label,id,current='',accept='image/png,image/jpeg,image/webp'){return `<label class="muted">${label}</label><div class="row" style="gap:8px;align-items:center"><input class="input" id="f_${id}" value="${esc(current||'')}" placeholder="Image URL or upload below"><input id="up_${id}" type="file" accept="${accept}" style="max-width:180px" onchange="readImageFile(this,'f_${id}')"></div><div id="preview_${id}" class="muted" style="margin-top:6px">${current?`<img src="${esc(current)}" style="max-width:110px;max-height:70px;border-radius:10px;object-fit:cover">`:''}</div>`}
function agencyLogoUploadField(current=''){return `<label class="muted">Agency Logo (upload image only)</label><input type="hidden" id="f_logo_url" value="${esc(current||'')}"><input class="input" id="up_logo_url" type="file" accept="image/png,image/jpeg,image/webp" onchange="readAgencyLogoFile(this)"><div id="preview_logo_url" style="margin-top:8px">${current?`<img src="${esc(current)}" alt="Agency logo preview" style="max-width:140px;max-height:70px;object-fit:contain;border-radius:8px">`:''}</div><p class="muted">PNG, JPG or WebP. Testing limit: 500 KB. No image URL required.</p>`}
function readAgencyLogoFile(input){const f=input?.files?.[0];if(!f)return;if(!/^image\/(png|jpeg|webp)$/.test(f.type))return alert('Upload a PNG, JPG or WebP image.');if(f.size>500*1024)return alert('For this testing build, agency logo must be 500 KB or smaller.');const r=new FileReader();r.onload=()=>{const el=$('f_logo_url');if(el)el.value=r.result;const p=$('preview_logo_url');if(p)p.innerHTML=`<img src="${r.result}" alt="Agency logo preview" style="max-width:140px;max-height:70px;object-fit:contain;border-radius:8px">`;};r.readAsDataURL(f)}
function readImageFile(input,targetId){const f=input?.files?.[0];if(!f)return;if(!/^image\/(png|jpeg|webp)$/.test(f.type))return alert('Please upload PNG, JPG or WebP image.');if(f.size>3*1024*1024)return alert('Image must be 3 MB or smaller for testing.');const r=new FileReader();r.onload=()=>{const el=$(targetId);if(el)el.value=r.result;const p=$('preview_'+targetId.replace(/^f_/,'').replace(/^f_/,'')||'');if(p)p.innerHTML=`<img src="${r.result}" style="max-width:110px;max-height:70px;border-radius:10px;object-fit:cover">`;};r.readAsDataURL(f)}
function imageValue(id){return $(id)?.value||''}
function customerProfileFields(prefix=''){return `<div class="card" style="margin-top:10px"><h4>Business Details</h4>${formField('Business Name','business_name')}${formField('Contact Person Name','name')}${formField('Email / Login ID','email','name@example.com')}<label class="muted">Mobile Number</label><div class="row" style="gap:8px;flex-wrap:nowrap"><input class="input" id="f_country_code" value="+91" maxlength="5" style="flex:0 0 72px"><input class="input" id="f_phone" placeholder="10-digit mobile number" maxlength="10" inputmode="numeric" style="flex:1;min-width:0" oninput="this.value=this.value.replace(/\D/g,'').slice(0,10)"></div>${formField('Business Category / Industry','industry','e.g. Real Estate')}${formField('Business Address','address')}${formField('City','city')}${formField('State','state')}${formField('PIN Code','pincode')}${formField('Website URL (optional)','website_url','https://')}${formField('Instagram URL (optional)','instagram_url','https://instagram.com/...')}${formField('Facebook URL (optional)','facebook_url','https://facebook.com/...')}${imageUploadField('Business Logo','logo_url')} ${imageUploadField('Owner / Profile Photo','owner_photo_url')}</div><div class="card" style="margin-top:10px"><h4>Billing / GST</h4>${formField('Billing Name / Legal Business Name','billing_name')}${formField('PAN (optional)','pan')}${formField('GSTIN (optional)','gstin')}<label class="muted">GST Status</label><select class="input" id="f_gst_status"><option>Not Registered</option><option>GST Registered</option><option>Composition / Other</option></select>${formField('Billing Address','billing_address')}${formField('Internal Notes','notes')}</div>`}
function newCustomer(){modal('Add New Customer',customerProfileFields()+`<div class="card" style="margin-top:10px">${formField('Plan / Service','plan','Meta Ads / Website')}<label class="muted">Customer Login Password</label><input class="input" id="f_login_password" type="password" minlength="8" autocomplete="new-password" placeholder="Minimum 8 characters"><div class="muted">Required: Business Name, Contact Person, Email, Mobile, Plan and Login Password.</div></div><button class="btn primary" onclick="saveCustomer()">Create Customer + Login</button>`)}
async function saveCustomer(){const name=$('f_name').value.trim(),business=$('f_business_name').value.trim(),email=$('f_email').value.trim().toLowerCase(),code=$('f_country_code').value.trim(),digits=$('f_phone').value.replace(/\D/g,''),phone=code.replace(/\s/g,'')+digits,plan=$('f_plan').value.trim(),password=$('f_login_password').value;if(!name||!business||!email||!digits||!plan||!password)return alert('Please fill the required customer fields.');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return alert('Please enter a valid email address.');if(!/^\+\d{1,4}$/.test(code)||!/^\d{10}$/.test(digits))return alert('Enter a valid country code and exactly 10 mobile digits.');if(password.length<8)return alert('Customer password must be at least 8 characters.');try{const body={name,business_name:business,email,phone,plan,login_password:password,industry:$('f_industry').value,address:$('f_address').value,city:$('f_city').value,state:$('f_state').value,pincode:$('f_pincode').value,website_url:$('f_website_url').value,instagram_url:$('f_instagram_url').value,facebook_url:$('f_facebook_url').value,logo_url:$('f_logo_url').value,owner_photo_url:$('f_owner_photo_url').value,billing_name:$('f_billing_name').value,pan:$('f_pan').value,gstin:$('f_gstin').value,gst_status:$('f_gst_status').value,billing_address:$('f_billing_address').value,notes:$('f_notes').value};const r=await api('/customers',{method:'POST',body:JSON.stringify(body)});closeModal();alert('Customer created successfully.\nLogin: '+r.login.email+' / '+r.login.temporary_password);customers()}catch(e){alert(e.message)}}
async function editCustomer(id){const c=(await api('/customers')).find(x=>Number(x.id)===Number(id));if(!c)return;modal('Edit Customer Profile',customerProfileFields()+`<button class="btn primary" onclick="saveCustomerEdit(${id})">Save Customer Profile</button>`);['business_name','name','email','industry','address','city','state','pincode','website_url','instagram_url','facebook_url','logo_url','owner_photo_url','billing_name','pan','gstin','billing_address','notes'].forEach(k=>{if($('f_'+k))$('f_'+k).value=c[k]||''});$('f_country_code').value=(String(c.phone||'').match(/^\+\d{1,4}/)||['+91'])[0];$('f_phone').value=String(c.phone||'').replace(/^\+\d{1,4}[- ]?/,'');$('f_gst_status').value=c.gst_status||'Not Registered'}
async function saveCustomerEdit(id){try{const code=$('f_country_code').value.trim(),digits=$('f_phone').value.replace(/\D/g,'');if(!/^\+\d{1,4}$/.test(code)||!/^\d{10}$/.test(digits))return alert('Enter a valid mobile number.');const body={name:$('f_name').value.trim(),business_name:$('f_business_name').value.trim(),email:$('f_email').value.trim().toLowerCase(),phone:code+digits,industry:$('f_industry').value,address:$('f_address').value,city:$('f_city').value,state:$('f_state').value,pincode:$('f_pincode').value,website_url:$('f_website_url').value,instagram_url:$('f_instagram_url').value,facebook_url:$('f_facebook_url').value,logo_url:$('f_logo_url').value,owner_photo_url:$('f_owner_photo_url').value,billing_name:$('f_billing_name').value,pan:$('f_pan').value,gstin:$('f_gstin').value,gst_status:$('f_gst_status').value,billing_address:$('f_billing_address').value,notes:$('f_notes').value};await api('/customers/'+id,{method:'PATCH',body:JSON.stringify(body)});closeModal();customers()}catch(e){alert(e.message)}}
async function toggleCustomer(id,status){try{await api('/customers/'+id+'/status',{method:'PATCH',body:JSON.stringify({status})});customers()}catch(e){alert(e.message)}}
function templateShortcut(type){const label={form:'Form',funnel:'Funnel',website:'Website',landing:'Landing Page'}[type]||'Template';const list=TEMPLATES.filter(t=>t.type===type);return `<div class="card template-shortcut"><div class="row"><div style="margin-right:auto"><h4>📚 Ready ${label} Templates</h4><div class="muted">${list.length} ready-made ${label.toLowerCase()} templates. Select one to create instantly.</div></div><button class="btn dark mini" onclick="openPage('templates')">All Templates</button></div><div class="grid" style="margin-top:10px">${list.map(t=>`<div class="card"><div class="muted">Ready Template</div><h3>${t.name}</h3><p class="muted">${t.fields?t.fields.slice(0,4).join(', '):t.steps?t.steps.join(' → '):t.pages.slice(0,5).join(' • ')}</p><div class="row"><button class="btn mini" onclick="previewTemplate(${t.id})">Preview</button><button class="btn primary mini" onclick="useTemplate(${t.id})">Use ${label}</button></div></div>`).join('')}</div></div>`}
async function templates(){const d=TEMPLATES;const groups={form:'Forms',funnel:'Funnels',website:'Multi-Page Websites',landing:'Landing Pages'};const websiteCount=d.filter(x=>x.type==='website').length;const formCount=d.filter(x=>x.type==='form').length;const funnelCount=d.filter(x=>x.type==='funnel').length;const landingCount=d.filter(x=>x.type==='landing').length;$('panel').innerHTML=`<div class="card"><div class="row"><h3 style="margin-right:auto">📚 Ready Template Library</h3><span class="muted">${d.length} templates • ${formCount} Forms • ${funnelCount} Funnels • ${websiteCount} Multi-Page Websites • ${landingCount} Landing Pages</span></div><div class="row" style="margin:10px 0"><button class="btn dark mini" onclick="filterTemplates('all')">All</button><button class="btn mini" onclick="filterTemplates('form')">Forms</button><button class="btn mini" onclick="filterTemplates('funnel')">Funnels</button><button class="btn mini" onclick="filterTemplates('website')">Multi-Page Websites</button><button class="btn mini" onclick="filterTemplates('landing')">Landing Pages</button></div><div id="templateGrid" class="grid">${d.map(t=>`<div class="card template-item" data-type="${t.type}"><div class="muted">${groups[t.type]}</div><h3>${t.name}</h3><p class="muted">${t.fields?t.fields.join(', '):t.steps?t.steps.join(' → '):t.landing_sections?t.landing_sections.join(' • '):(t.pages||[]).join(' • ')}</p><div class="row"><button class="btn" onclick="previewTemplate(${t.id})">Preview</button><button type="button" class="btn primary" onclick="useTemplate(${t.id})">Use Template →</button></div></div>`).join('')}</div></div>`}function filterTemplates(type){document.querySelectorAll('.template-item').forEach(x=>x.style.display=(type==='all'||x.dataset.type===type)?'block':'none')}
