    const shell=(body,extra='')=>localizeHtml(`<div style="border:1px solid ${bg}20;border-radius:22px;overflow:hidden;background:#fff;box-shadow:0 28px 80px #0f172a22;font-family:Arial,sans-serif">${nav}${body}${footer}</div>`,lang);
