function ownerOnly(){ if(me?.role!=='platform_owner'){alert('Only Platform Owner can manage this setting.');return false;} return true; }
function money(n){return '₹'+Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:2});}
function allCustomers(){return Array.isArray(MOCK.customers)?MOCK.customers:[];}
function accountName(c){return c?.business_name||c?.name||c?.display_name||'Account';}
function couponBalance(type,id){return MOCK.referral_credits.filter(x=>x.referrer_type===type&&String(x.referrer_id)===String(id)).reduce((s,x)=>s+Number(x.amount||0)-Number(x.used||0),0);}
function referralCode(type,id){return type==='agency'?'APEX-AG-'+String(id).replace(/\W/g,'').slice(-8):'APEX-C-'+String(id).replace(/\W/g,'').slice(-8);}
function nextInvoiceNo(){const n=MOCK.invoices.reduce((m,x)=>Math.max(m,Number(String(x.invoice_no||'').match(/(\d+)$/)?.[1]||0)),0)+1;return 'AJ-'+String(n).padStart(5,'0');}
function normalizedPhone(v){return String(v||'').replace(/\D/g,'').replace(/^91(?=\d{10}$)/,'');}
function findDuplicateCustomer(email,phone,skipId){return allCustomers().find(c=>String(c.id)!==String(skipId||'')&&(String(c.email||'').trim().toLowerCase()===String(email||'').trim().toLowerCase()|| (normalizedPhone(c.phone)&&normalizedPhone(c.phone)===normalizedPhone(phone))));}
function issueReferralReward(code,newType,newId,newName){
  const clean=String(code||'').trim().toUpperCase(); if(!clean)return null;
  let ref=null,type='customer';
  for(const c of allCustomers()){if((c.referral_code||referralCode('customer',c.id)).toUpperCase()===clean){ref=c;type='customer';break;}}
  if(!ref){const a=(MOCK.agencies||[]).find(a=>(a.referral_code||referralCode('agency',a.id)).toUpperCase()===clean);if(a){ref=a;type='agency';}}
  if(!ref)throw Error('Referral Code invalid. Check the code and try again.');
  if((type==='customer'&&String(ref.id)===String(newId)&&newType==='customer')||(type==='agency'&&String(ref.id)===String(newId)&&newType==='agency'))throw Error('Self-referral is not allowed.');
  if(MOCK.referral_events.some(e=>e.new_type===newType&&String(e.new_id)===String(newId)))throw Error('This new account already has a referral recorded.');
  const amount=Number(MOCK.referral_reward_amount||500); const event={id:Date.now(),referrer_type:type,referrer_id:ref.id,referrer_name:accountName(ref),new_type:newType,new_id:newId,new_name:newName,code:clean,amount,status:'Approved',created_at:new Date().toISOString()};
  MOCK.referral_events.unshift(event); MOCK.referral_credits.unshift({id:Date.now()+1,referrer_type:type,referrer_id:ref.id,event_id:event.id,amount,used:0,created_at:new Date().toISOString(),description:'Referral reward for '+newName});
  MOCK.notifications.unshift({id:Date.now()+2,payload:{title:'Referral coupon credited',message:money(amount)+' coupon credit added to '+accountName(ref)+' account.'}});
  return event;
}
function printHTML(title,html){const w=window.open('','_blank');if(!w){alert('Allow pop-ups to Print / Save PDF.');return;}w.document.write(`<!doctype html><html><head><title>${esc(title)}</title><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;color:#111;padding:26px}h1{font-size:22px;margin-bottom:4px}.muted{color:#555;font-size:12px}.brand{font-weight:bold;color:#111}.brand span{color:#e87924}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{padding:9px;border:1px solid #ccc;text-align:left;font-size:12px}th{background:#f2f4f7}.total{text-align:right;margin-top:18px;font-size:15px}.sign{margin-top:50px;display:flex;justify-content:space-between}@media print{button{display:none}}</style></head><body><div class="brand">APEXJOV <span>MEDIA</span></div><h1>${esc(title)}</h1><p class="muted">Generated ${new Date().toLocaleString('en-IN')}</p>${html}<div class="sign"><div>Customer / Authorized By: __________________</div><div>Signature & Stamp: __________________</div></div><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>`);w.document.close();}
function reportTable(headers,rows){return `<table><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${esc(String(x??''))}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}

/* Working Sales / Operations / Inbox / Calendar / Tasks / Lead Automation modules */
async function moduleManager(title,key,fields){
  const records=Array.isArray(MOCK[key])?MOCK[key]:(MOCK.module_records[key]||[]); MOCK[key]=records;
  const rows=records.map((r,i)=>{const p=r.payload||r;return `<div class="card"><div class="row"><h3 style="margin-right:auto">${esc(p[fields[0]]||p.title||p.name||title+' '+(i+1))}</h3><span class="badge">${esc(p.Status||p.status||'Open')}</span></div><div class="grid">${fields.slice(1).map(f=>`<div><small class="muted">${esc(f)}</small><div>${esc(p[f]||p[f.toLowerCase().replace(/\s/g,'_')]||'—')}</div></div>`).join('')}</div><div class="row" style="margin-top:10px"><button class="btn" onclick="editModuleRecord('${key}',${r.id})">Edit</button><button class="btn" onclick="printModuleRecord('${key}',${r.id})">Print / PDF</button><button class="btn" onclick="deleteModuleRecord('${key}',${r.id})">Delete</button></div></div>`}).join('');
  $('panel').innerHTML=`<div class="card"><div class="row"><h3 style="margin-right:auto">${esc(title)}</h3><button class="btn primary" onclick="newModuleRecord('${key}')">+ Add ${esc(title.replace(/s$/,''))}</button></div><p class="muted">Create, edit and track records. Changes are saved in this browser's testing data.</p><div class="grid">${rows||'<div class="card">No records yet. Use Add to create the first record.</div>'}</div></div>`;
}
function moduleFields(key){return ({sales:['Opportunity','Customer','Value','Stage','Expected Close'],operations:['Task / Operation','Owner','Due Date','Status'],inbox:['Contact','Channel','Subject','Status'],calendar:['Title','Date','Time','Customer','Status'],tasks:['Task','Owner','Due Date','Priority','Status'],lead_automation:['Rule Name','Trigger','Action','Status']})[key]||['Name','Description','Status'];}
function newModuleRecord(key,id){if(!['platform_owner','agency_admin'].includes(me?.role)){alert('You do not have access.');return;}const old=(MOCK[key]||[]).find(x=>String(x.id)===String(id));const p=old?.payload||old||{};const fs=moduleFields(key);const html=fs.map((f,i)=>{const id2='mf_'+i;let type=/date/i.test(f)?'date':/value|amount/i.test(f)?'number':'text';if(/status|stage|priority/i.test(f)){const opts=/priority/i.test(f)?['Low','Medium','High','Urgent']:/stage/i.test(f)?['New','Contacted','Interested','Converted','Lost']:['Open','In Progress','Completed','On Hold','Closed'];return `<label class="muted">${esc(f)}</label><select class="input" id="${id2}">${opts.map(o=>`<option ${String(p[f]||p[f.toLowerCase()]||'')===o?'selected':''}>${o}</option>`).join('')}</select>`;}return `<label class="muted">${esc(f)}</label><input class="input" id="${id2}" type="${type}" value="${esc(p[f]||p[f.toLowerCase().replace(/\s/g,'_')]||'')}">`;}).join('');modal((old?'Edit ':'Add ')+key.replace(/_/g,' '),html+`<button class="btn primary" onclick="saveModuleRecord('${key}',${old?old.id:'null'})">Save</button>`);}
function editModuleRecord(key,id){newModuleRecord(key,id)}
function saveModuleRecord(key,id){const fs=moduleFields(key),p={};fs.forEach((f,i)=>p[f]=$('mf_'+i)?.value||'');MOCK[key]=Array.isArray(MOCK[key])?MOCK[key]:[];if(id){const r=MOCK[key].find(x=>String(x.id)===String(id));if(r){if(r.payload)r.payload=p;else Object.assign(r,p);}}else MOCK[key].unshift({id:Date.now(),...p,created_at:new Date().toISOString()});persistMock();closeModal();moduleManager(key.replace(/_/g,' ').replace(/^./,s=>s.toUpperCase()),key,fs);}
function deleteModuleRecord(key,id){if(!confirm('Delete this record?'))return;MOCK[key]=(MOCK[key]||[]).filter(x=>String(x.id)!==String(id));persistMock();moduleManager(key.replace(/_/g,' ').replace(/^./,s=>s.toUpperCase()),key,moduleFields(key));}
function printModuleRecord(key,id){const r=(MOCK[key]||[]).find(x=>String(x.id)===String(id));if(!r)return;const p=r.payload||r;printHTML(key.replace(/_/g,' ').toUpperCase(),reportTable(['Field','Value'],Object.entries(p).map(([k,v])=>[k,typeof v==='object'?JSON.stringify(v):v])));}

/* Dedicated Finance, Invoice, Payment, Ledger and Expenses. */
function displayAccount(type,id){const x=type==='agency'?(MOCK.agencies||[]).find(c=>String(c.id)===String(id)):allCustomers().find(c=>String(c.id)===String(id));return x?accountName(x):'Account';}
async function billing(){const invoices=MOCK.invoices||[],payments=MOCK.payments||[];const outstanding=invoices.reduce((s,i)=>s+Math.max(0,Number(i.total??i.amount??0)-Number(i.paid_amount||0)),0);const paid=payments.reduce((s,p)=>s+(String(p.status||'SUCCESS').toUpperCase()==='SUCCESS'?Number(p.amount||0):0),0);const invCards=invoices.map(i=>{const total=Number(i.total??i.amount??0),balance=Math.max(0,total-Number(i.paid_amount||0));return `<div class="card"><div class="row"><b style="margin-right:auto">${esc(i.invoice_no||'Invoice')}</b><span class="badge">${esc(balance===0?'Paid':i.paid_amount?'Partially Paid':i.status||'Unpaid')}</span></div><p>${esc(i.customer_name||displayAccount(i.account_type||'customer',i.account_id||i.customer_id))} • ${money(total)}</p><p class="muted">Paid ${money(i.paid_amount||0)} • Balance ${money(balance)} • Due ${esc(formatDateIN(i.due_date))}</p><div class="row"><button class="btn" onclick="printInvoice(${i.id})">Print / Save PDF</button><button class="btn" onclick="editInvoice(${i.id})">Edit</button></div></div>`}).join('');const payCards=payments.map(p=>`<div class="card"><div class="row"><b style="margin-right:auto">${money(p.amount)}</b><span class="badge">${esc(p.status||'SUCCESS')}</span></div><p>${esc(p.customer_name||displayAccount(p.account_type||'customer',p.account_id||p.customer_id))} • ${esc(p.payment_mode||p.provider||'Manual')}</p><p class="muted">Invoice: ${esc(p.invoice_no||'Not linked')} • ${esc(p.paid_at||'')}</p><div class="row"><button class="btn" onclick="printPayment(${p.id})">Print / Save PDF</button></div></div>`).join('');$('panel').innerHTML=`<div class="grid"><div class="card"><div class="row"><h3 style="margin-right:auto">🧾 Invoices</h3><button class="btn primary" onclick="newInvoice()">+ Create Invoice</button></div>${invCards||'<p class="muted">No invoices.</p>'}</div><div class="card"><div class="row"><h3 style="margin-right:auto">💳 Payments</h3><button class="btn primary" onclick="manualPayment()">+ Record Payment</button></div>${payCards||'<p class="muted">No payments.</p>'}</div></div><div class="grid" style="margin-top:14px"><div class="card"><h3>Outstanding Summary</h3><div class="stats">${money(outstanding)}</div><button class="btn" onclick="openPage('reports')">Open Accounting Reports</button></div><div class="card"><h3>Payments Collected</h3><div class="stats">${money(paid)}</div><button class="btn" onclick="printLedger()">Print / Save Ledger PDF</button></div></div>`;}
function newInvoice(){const customers=allCustomers();if(!customers.length&&!(MOCK.agencies||[]).length)return alert('Create a customer or agency first.');const agencies=MOCK.agencies||[];const opts=[...customers.map(c=>`<option value="customer:${c.id}">Customer: ${esc(accountName(c))}</option>`),...agencies.map(a=>`<option value="agency:${a.id}">Agency: ${esc(accountName(a))}</option>`)].join('');modal('Create Professional Invoice',`<label class="muted">Account (Customer / Agency)</label><select class="input" id="f_customer_id">${opts}</select><label class="muted">Invoice Type</label><select class="input" id="f_invoice_type"><option>Non-GST</option><option>GST</option></select>${formField('Service / Description','service_description','Digital Marketing Service')}${formField('Amount before GST','subtotal','0')}${formField('GST Rate %','gst_rate','0')}${formField('SAC / Service Code','sac_code','Optional')}${formField('Due Date','due_date','DD/MM/YYYY')}<div id="couponHint" class="question">Coupon balance: calculated for selected customer after selection.</div><label class="muted">Coupon to apply (optional)</label><input class="input" id="f_coupon_use" type="number" min="0" value="0"><button class="btn primary" onclick="saveInvoice()">Create Invoice</button>`);$('f_customer_id').addEventListener('change',updateCouponHint);updateCouponHint();}
function updateCouponHint(){const raw=$('f_customer_id')?.value||'',parts=raw.includes(':')?raw.split(':'):['customer',raw],type=parts[0],id=parts[1],b=couponBalance(type,id);const h=$('couponHint');if(h)h.textContent='Available coupon credit: '+money(b);const inp=$('f_coupon_use');if(inp){inp.max=b;}}
function saveInvoice(){const raw=$('f_customer_id').value,parts=raw.includes(':')?raw.split(':'):['customer',raw],account_type=parts[0],cid=parts[1],c=account_type==='agency'?(MOCK.agencies||[]).find(x=>String(x.id)===String(cid)):allCustomers().find(x=>String(x.id)===String(cid));const subtotal=Number($('f_subtotal').value||0),rate=Number($('f_gst_rate').value||0),coupon=Number($('f_coupon_use').value||0),available=couponBalance(account_type,cid);if(!c)return alert('Select a customer.');if(!(subtotal>0))return alert('Invoice amount must be greater than zero.');if(coupon<0||coupon>available||coupon>subtotal*(1+rate/100))return alert('Coupon adjustment exceeds available credit or invoice total.');const tax=$('f_invoice_type').value==='GST'?subtotal*rate/100:0,total=+(subtotal+tax).toFixed(2),id=Date.now(),invoice={id,invoice_no:nextInvoiceNo(),account_type,account_id:Number(cid),customer_id:account_type==='customer'?Number(cid):null,customer_name:accountName(c),invoice_type:$('f_invoice_type').value,description:$('f_service_description').value,subtotal,tax,gst_rate:rate,sac_code:$('f_sac_code').value,total:Math.max(0,+(total-coupon).toFixed(2)),gross_total:total,coupon_applied:coupon,paid_amount:0,status:'Unpaid',due_date:$('f_due_date').value||'',created_at:new Date().toISOString()};MOCK.invoices.unshift(invoice);if(coupon>0){let left=coupon;for(const cr of MOCK.referral_credits.filter(x=>x.referrer_type===account_type&&String(x.referrer_id)===String(cid))){const avail=Number(cr.amount||0)-Number(cr.used||0),use=Math.min(avail,left);if(use>0){cr.used=Number(cr.used||0)+use;left-=use;if(!left)break;}}}MOCK.audit_logs.unshift({id:id+1,payload:{action:'INVOICE_CREATE',invoice_no:invoice.invoice_no,customer_id:cid}});persistMock();closeModal();billing();}
function editInvoice(id){const i=MOCK.invoices.find(x=>String(x.id)===String(id));if(!i)return;modal('Edit Invoice',`${formField('Due Date','due_date',formatDateIN(i.due_date))}${formField('Service / Description','service_description',i.description||'')}${formField('Notes','invoice_notes',i.notes||'')}<button class="btn primary" onclick="saveInvoiceEdit(${id})">Save Changes</button>`);}
function saveInvoiceEdit(id){const i=MOCK.invoices.find(x=>String(x.id)===String(id));if(!i)return;if(!validDateIN($('f_due_date').value)){alert('Enter Due Date as DD/MM/YYYY');return;}i.due_date=dateInputISO($('f_due_date').value);i.description=$('f_service_description').value;i.notes=$('f_invoice_notes').value;persistMock();closeModal();billing();}
function invoiceMarkup(i){const c=i.account_type==='agency'?(MOCK.agencies||[]).find(x=>String(x.id)===String(i.account_id||i.customer_id)):allCustomers().find(x=>String(x.id)===String(i.customer_id));return `<p><b>Invoice No:</b> ${esc(i.invoice_no)} &nbsp; <b>Date:</b> ${esc(formatDateIN(i.created_at))}</p><p><b>Bill To:</b> ${esc(accountName(c)||i.customer_name)}<br>${esc(c?.address||c?.billing_address||'')}<br>${esc(c?.email||'')} • ${esc(c?.phone||'')}</p>${reportTable(['Description','Subtotal','Tax','Total'],[[i.description||'Service',money(i.subtotal??i.amount),money(i.tax||0),money(i.gross_total??i.total??i.amount)]])}<div class="total">Coupon/Credit: ${money(i.coupon_applied||0)}<br><b>Invoice Total: ${money(i.total??i.amount)}</b><br>Paid: ${money(i.paid_amount||0)}<br><b>Balance Due: ${money(Math.max(0,Number(i.total??i.amount)-Number(i.paid_amount||0)))}</b></div><p class="muted">${esc(i.invoice_type||'Non-GST')} • ${i.gst_rate?`GST ${i.gst_rate}%`:'No GST charged'} • Due ${esc(formatDateIN(i.due_date))}</p>`;}
function printInvoice(id){const i=MOCK.invoices.find(x=>String(x.id)===String(id));if(i)printHTML('TAX INVOICE / SERVICE INVOICE',invoiceMarkup(i));}
function manualPayment(){const unpaid=(MOCK.invoices||[]).filter(i=>Number(i.total??i.amount??0)>Number(i.paid_amount||0));if(!unpaid.length)return alert('No unpaid invoices. Create an invoice first.');const opts=unpaid.map(i=>`<option value="${i.id}">${esc(i.invoice_no)} — ${esc(i.customer_name||accountName(allCustomers().find(c=>String(c.id)===String(i.customer_id))))} — Balance ${money(Number(i.total??i.amount)-Number(i.paid_amount||0))}</option>`).join('');modal('Record Payment & Link Invoice',`<label class="muted">Invoice Number</label><select class="input" id="f_invoice_id" onchange="paymentInvoiceChanged()">${opts}</select><div id="paymentBalance" class="question"></div>${formField('Received Amount','amount','0')}<label class="muted">Payment Mode</label><select class="input" id="f_payment_mode"><option>Cash</option><option>UPI</option><option>Bank Transfer</option><option>Cheque</option><option>Other</option></select>${formField('Transaction ID / UTR','transaction_ref','Optional reference')}${formField('Payment Date','paid_at',new Date().toISOString().slice(0,10))}${formField('Notes','notes','Optional')}<button class="btn primary" onclick="saveManualPayment()">Save Payment</button>`);paymentInvoiceChanged();}
function paymentInvoiceChanged(){const i=MOCK.invoices.find(x=>String(x.id)===String($('f_invoice_id')?.value));const b=$('paymentBalance');if(i&&b)b.textContent='Invoice '+i.invoice_no+' • Total '+money(i.total??i.amount)+' • Paid '+money(i.paid_amount||0)+' • Balance '+money(Math.max(0,Number(i.total??i.amount)-Number(i.paid_amount||0)));const a=$('f_amount');if(i&&a)a.value=Math.max(0,Number(i.total??i.amount)-Number(i.paid_amount||0));}
function saveManualPayment(){const i=MOCK.invoices.find(x=>String(x.id)===String($('f_invoice_id').value));const amount=Number($('f_amount').value||0);if(!i)return alert('Select an invoice.');const balance=Math.max(0,Number(i.total??i.amount)-Number(i.paid_amount||0));if(!(amount>0)||amount>balance)return alert('Payment must be greater than zero and cannot exceed invoice balance.');const p={id:Date.now(),account_type:i.account_type||'customer',account_id:i.account_id||i.customer_id,customer_id:i.customer_id,customer_name:i.customer_name,invoice_id:i.id,invoice_no:i.invoice_no,amount,payment_mode:$('f_payment_mode').value,transaction_ref:$('f_transaction_ref').value,paid_at:$('f_paid_at').value||new Date().toISOString().slice(0,10),notes:$('f_notes').value,status:'SUCCESS'};MOCK.payments.unshift(p);i.paid_amount=Number(i.paid_amount||0)+amount;i.status=i.paid_amount>=Number(i.total??i.amount)?'Paid':'Partially Paid';MOCK.audit_logs.unshift({id:p.id+1,payload:{action:'PAYMENT_RECEIVED',invoice_no:i.invoice_no,amount}});persistMock();closeModal();billing();}
function printPayment(id){const p=MOCK.payments.find(x=>String(x.id)===String(id));if(!p)return;const i=MOCK.invoices.find(x=>String(x.id)===String(p.invoice_id));printHTML('PAYMENT RECEIPT',`<p><b>Receipt No:</b> ${esc('RCPT-'+p.id)}<br><b>Payment Date:</b> ${esc(p.paid_at||'')}<br><b>Customer:</b> ${esc(p.customer_name||accountName(p.account_type==='agency'?(MOCK.agencies||[]).find(c=>String(c.id)===String(p.account_id||p.customer_id)):allCustomers().find(c=>String(c.id)===String(p.customer_id))))}<br><b>Invoice:</b> ${esc(p.invoice_no||'—')}</p>${reportTable(['Amount','Mode','Reference','Status'],[[money(p.amount),p.payment_mode,p.transaction_ref,p.status]])}<p class="total"><b>Amount Received: ${money(p.amount)}</b><br>Invoice Balance: ${money(i?Number(i.total??i.amount)-Number(i.paid_amount||0):0)}</p>`);}
function ledgerRows(){const rows=[];for(const i of MOCK.invoices||[])rows.push({date:(i.created_at||'').slice(0,10),account:i.customer_name||accountName(i.account_type==='agency'?(MOCK.agencies||[]).find(c=>String(c.id)===String(i.account_id||i.customer_id)):allCustomers().find(c=>String(c.id)===String(i.customer_id))),ref:i.invoice_no,type:'Invoice',debit:Number(i.gross_total??i.total??i.amount??0),credit:0,customer_id:i.account_id||i.customer_id,account_type:i.account_type||'customer'});for(const p of MOCK.payments||[])rows.push({date:p.paid_at||'',account:p.customer_name||accountName(p.account_type==='agency'?(MOCK.agencies||[]).find(c=>String(c.id)===String(p.account_id||p.customer_id)):allCustomers().find(c=>String(c.id)===String(p.customer_id))),ref:p.invoice_no||'Payment',type:'Payment',debit:0,credit:Number(p.amount||0),customer_id:p.account_id||p.customer_id,account_type:p.account_type||'customer'});for(const c of MOCK.referral_credits||[])rows.push({date:c.created_at?.slice(0,10)||'',account:accountName(c.referrer_type==='agency'?(MOCK.agencies||[]).find(x=>String(x.id)===String(c.referrer_id)):allCustomers().find(x=>String(x.id)===String(c.referrer_id)))||'Referrer',ref:'REF-'+c.event_id,type:'Referral Coupon Credit',debit:0,credit:Number(c.amount||0),customer_id:c.referrer_id,account_type:c.referrer_type});return rows.sort((a,b)=>String(a.date).localeCompare(String(b.date)));}
function printLedger(type,id){let rows=ledgerRows();if(type&&id!=null)rows=rows.filter(r=>r.account_type===type&&String(r.customer_id)===String(id));let bal=0;const out=rows.map(r=>{bal+=r.debit-r.credit;return [formatDateIN(r.date),r.account,r.ref,r.type,money(r.debit),money(r.credit),money(bal)];});printHTML('CUSTOMER LEDGER STATEMENT',reportTable(['Date','Account','Reference','Type','Debit','Credit','Running Balance'],out)+`<div class="total"><b>Closing Balance: ${money(bal)}</b></div>`);}

/* Expense, accounting and management reports */
async function expenses(){if(!ownerOnly()&&me.role!=='agency_admin')return;const list=MOCK.expenses||[];$('panel').innerHTML=`<div class="card"><div class="row"><h3 style="margin-right:auto">Expenses Management</h3><button class="btn primary" onclick="expenseForm()">+ Add Expense</button><button class="btn" onclick="printExpenses()">Print / Save PDF</button></div><div class="grid">${list.map(x=>`<div class="card"><div class="row"><b style="margin-right:auto">${esc(x.title)}</b><b>${money(x.amount)}</b></div><p>${esc(x.category)} • ${esc(formatDateIN(x.date))} • ${esc(x.payment_mode||'')}</p><p class="muted">${esc(x.notes||'')}</p><div class="row"><button class="btn" onclick="expenseForm(${x.id})">Edit</button><button class="btn" onclick="deleteExpense(${x.id})">Delete</button></div></div>`).join('')||'<p class="muted">No expenses recorded.</p>'}</div></div>`;}
function expenseForm(id){if(!ownerOnly()&&me.role!=='agency_admin')return;const x=(MOCK.expenses||[]).find(y=>String(y.id)===String(id))||{};modal(id?'Edit Expense':'Add Expense',`${formField('Expense Name','expense_title',x.title||'')}${formField('Category','expense_category',x.category||'Software / Hosting / Marketing')}${formField('Amount','expense_amount',x.amount||'0')}${formField('Date','expense_date',x.date||new Date().toISOString().slice(0,10))}<label class="muted">Payment Mode</label><select class="input" id="f_expense_mode"><option>Cash</option><option>UPI</option><option>Bank Transfer</option><option>Card</option><option>Other</option></select>${formField('Notes','expense_notes',x.notes||'')}<button class="btn primary" onclick="saveExpense(${id||'null'})">Save Expense</button>`);}
function saveExpense(id){const title=$('f_expense_title').value.trim(),amount=Number($('f_expense_amount').value||0);if(!title||amount<=0)return alert('Expense name and positive amount are required.');const obj={id:id||Date.now(),title,category:$('f_expense_category').value,date:$('f_expense_date').value||new Date().toISOString().slice(0,10),amount,payment_mode:$('f_expense_mode').value,notes:$('f_expense_notes').value};if(id){const i=MOCK.expenses.findIndex(x=>String(x.id)===String(id));if(i>=0)MOCK.expenses[i]=obj;}else MOCK.expenses.unshift(obj);persistMock();closeModal();expenses();}
function deleteExpense(id){if(!confirm('Delete expense?'))return;MOCK.expenses=MOCK.expenses.filter(x=>String(x.id)!==String(id));persistMock();expenses();}
function printExpenses(){printHTML('EXPENSE REPORT',reportTable(['Date','Expense','Category','Mode','Amount','Notes'],(MOCK.expenses||[]).map(x=>[x.date,x.title,x.category,x.payment_mode,money(x.amount),x.notes]))+`<div class="total"><b>Total Expenses: ${money((MOCK.expenses||[]).reduce((s,x)=>s+Number(x.amount||0),0))}</b></div>`);}
async function reports(){const customers=allCustomers(),invoices=MOCK.invoices||[],payments=MOCK.payments||[],ex=MOCK.expenses||[];const totalInvoice=invoices.reduce((s,x)=>s+Number(x.total??x.amount??0),0),received=payments.filter(x=>String(x.status||'SUCCESS').toUpperCase()==='SUCCESS').reduce((s,x)=>s+Number(x.amount||0),0),outstanding=invoices.reduce((s,x)=>s+Math.max(0,Number(x.total??x.amount??0)-Number(x.paid_amount||0)),0),expensesTotal=ex.reduce((s,x)=>s+Number(x.amount||0),0),profit=received-expensesTotal;const leads=(MOCK.crm||[]).length,agencies=(MOCK.agencies||[]).length;const categoryCounts={};customers.forEach(c=>{const k=c.industry||'Uncategorised';categoryCounts[k]=(categoryCounts[k]||0)+1;});$('panel').innerHTML=`<div class="card"><div class="row"><h3 style="margin-right:auto">Reports & Analytics</h3><button class="btn" onclick="printAccountingReport()">Print / Save PDF</button></div><div class="grid"><div class="card">Total Users<div class="stats">${(MOCK.users||[]).length}</div></div><div class="card">Customers<div class="stats">${customers.length}</div></div><div class="card">Agencies / Tenants<div class="stats">${agencies}</div></div><div class="card">Leads<div class="stats">${leads}</div></div><div class="card">Invoice Total<div class="stats">${money(totalInvoice)}</div></div><div class="card">Payments Received<div class="stats">${money(received)}</div></div><div class="card">Outstanding<div class="stats">${money(outstanding)}</div></div><div class="card">Expenses<div class="stats">${money(expensesTotal)}</div></div><div class="card">Net Cash Profit / Loss<div class="stats">${money(profit)}</div></div></div><h3 style="margin-top:16px">Customer Business Categories</h3>${reportTable(['Business Category','Users / Customers'],Object.entries(categoryCounts))}<div class="row" style="margin-top:14px"><button class="btn" onclick="openPage('expenses')">Manage Expenses</button><button class="btn" onclick="printLedger()">Customer Ledger PDF</button><button class="btn" onclick="printOutstanding()">Outstanding Report PDF</button></div><p class="muted">Testing summary only. Cash Profit/Loss uses received payments minus entered expenses; this is not a formal accrual-accounting statement.</p></div>`;}
function printAccountingReport(){const customers=allCustomers(),invoices=MOCK.invoices||[],payments=MOCK.payments||[],ex=MOCK.expenses||[];printHTML('ACCOUNTING REPORT',reportTable(['Metric','Amount / Count'],[['Total Users',(MOCK.users||[]).length],['Customers',customers.length],['Agencies',(MOCK.agencies||[]).length],['Leads',(MOCK.crm||[]).length],['Invoice Total',money(invoices.reduce((s,x)=>s+Number(x.total??x.amount??0),0))],['Payments Received',money(payments.reduce((s,x)=>s+Number(x.amount||0),0))],['Outstanding',money(invoices.reduce((s,x)=>s+Math.max(0,Number(x.total??x.amount??0)-Number(x.paid_amount||0)),0))],['Expenses',money(ex.reduce((s,x)=>s+Number(x.amount||0),0))]]));}
function printOutstanding(){const rows=(MOCK.invoices||[]).filter(i=>Number(i.total??i.amount??0)>Number(i.paid_amount||0)).map(i=>[i.invoice_no,i.customer_name||accountName(allCustomers().find(c=>String(c.id)===String(i.customer_id))),money(i.total??i.amount),money(i.paid_amount||0),money(Number(i.total??i.amount)-Number(i.paid_amount||0)),i.due_date||'']);printHTML('OUTSTANDING REPORT',reportTable(['Invoice','Customer','Invoice Total','Paid','Outstanding','Due Date'],rows));}

/* Plans & Pricing is a separate main sidebar module, not nested under agencies. */
async function plansPricing(){if(!ownerOnly())return;const cats=MOCK.pricing_categories||[];$('panel').innerHTML=`<div class="card"><div class="row"><h3 style="margin-right:auto">Plans & Pricing</h3><button class="btn primary" onclick="pricingCategoryForm()">+ Add Main Category</button></div><p class="muted">Manage Meta Ads, Google Ads, Website Design, Rented Portal and Tenant/Agency plans separately. Prices here are testing values until confirmed.</p><div class="grid">${cats.map(c=>`<div class="card"><div class="row"><h3 style="margin-right:auto">${esc(c.name)}</h3><button class="btn mini" onclick="pricingCategoryForm('${c.id}')">Edit Category</button></div><p class="muted">${(c.plans||[]).length} plans</p><button class="btn primary" onclick="pricingPlanForm('${c.id}')">+ Add Plan</button>${(c.plans||[]).map(p=>`<div class="question"><div class="row"><b style="margin-right:auto">${esc(p.name)}</b><b>${money(p.price)}</b></div><p class="muted">${esc(p.cycle||'One-time')} • ${esc(p.features||'')} • ${p.status||'Active'}</p><div class="row"><button class="btn mini" onclick="pricingPlanForm('${c.id}','${p.id}')">Edit</button><button class="btn mini" onclick="togglePricingPlan('${c.id}','${p.id}')">${p.status==='Inactive'?'Activate':'Deactivate'}</button></div></div>`).join('')}</div>`).join('')}</div></div>`;}
function pricingCategoryForm(id){if(!ownerOnly())return;const c=(MOCK.pricing_categories||[]).find(x=>String(x.id)===String(id))||{};modal(id?'Edit Main Category':'Add Main Category',`${formField('Category Name','category_name',c.name||'e.g. Meta Ads')}${formField('Category ID (letters/numbers/hyphen)','category_id',c.id||'e.g. meta_ads')}<button class="btn primary" onclick="savePricingCategory('${id||''}')">Save Category</button>`);}
function savePricingCategory(id){const name=$('f_category_name').value.trim(),newId=($('f_category_id').value.trim()||name.toLowerCase().replace(/[^a-z0-9]+/g,'-'));if(!name)return alert('Category name required.');if(id){const c=MOCK.pricing_categories.find(x=>String(x.id)===String(id));if(c)c.name=name;}else{if(MOCK.pricing_categories.some(x=>String(x.id)===newId))return alert('Category ID already exists.');MOCK.pricing_categories.push({id:newId,name,plans:[]});}persistMock();closeModal();plansPricing();}
function pricingPlanForm(catId,planId){if(!ownerOnly())return;const c=MOCK.pricing_categories.find(x=>String(x.id)===String(catId));if(!c)return;const p=(c.plans||[]).find(x=>String(x.id)===String(planId))||{};modal(planId?'Edit Plan':'Add Plan',`${formField('Plan Name','plan_name',p.name||'')}${formField('Price (INR)','plan_price',p.price||0)}<label class="muted">Billing Cycle</label><select class="input" id="f_plan_cycle">${['7 Days','15 Days','Monthly','Quarterly','Half-Yearly','Yearly','One-time'].map(x=>`<option ${p.cycle===x?'selected':''}>${x}</option>`).join('')}</select>${formField('Validity in Days','plan_validity',p.validity||0)}${formField('User Limit (if applicable)','plan_user_limit',p.user_limit||0)}${formField('WhatsApp Monthly Quota','plan_whatsapp_quota',p.whatsapp_quota||0)}<label class="muted">Included Features</label><textarea class="input" id="f_plan_features">${esc(p.features||'')}</textarea><button class="btn primary" onclick="savePricingPlan('${catId}','${planId||''}')">Save Plan</button>`);}
function savePricingPlan(catId,planId){const c=MOCK.pricing_categories.find(x=>String(x.id)===String(catId));if(!c)return;const p={id:planId||('plan-'+Date.now()),name:$('f_plan_name').value.trim(),price:Number($('f_plan_price').value||0),cycle:$('f_plan_cycle').value,validity:Number($('f_plan_validity').value||0),user_limit:Number($('f_plan_user_limit').value||0),whatsapp_quota:Number($('f_plan_whatsapp_quota').value||0),features:$('f_plan_features').value,status:'Active'};if(!p.name||p.price<0)return alert('Plan name and valid price required.');c.plans=c.plans||[];const i=c.plans.findIndex(x=>String(x.id)===String(planId));if(i>=0)c.plans[i]=p;else c.plans.push(p);persistMock();closeModal();plansPricing();}
function togglePricingPlan(catId,planId){const c=MOCK.pricing_categories.find(x=>String(x.id)===String(catId)),p=c?.plans.find(x=>String(x.id)===String(planId));if(p)p.status=p.status==='Inactive'?'Active':'Inactive';persistMock();plansPricing();}

/* Referral/Coupon management and notification editor */
async function referrals(){const events=MOCK.referral_events||[];const credits=MOCK.referral_credits||[];$('panel').innerHTML=`<div class="card"><div class="row"><h3 style="margin-right:auto">Referrals / Reviews</h3><button class="btn primary" onclick="referralSettings()">Referral Program Settings</button></div><p class="muted">Coupon benefit is credited to the existing referrer, never to the new account. One reward per unique referred account.</p><div class="grid"><div class="card"><h3>Reward Amount</h3><div class="stats">${money(MOCK.referral_reward_amount||500)}</div><p class="muted">Testing default; owner can change it.</p></div><div class="card"><h3>Unspent Coupon Credit</h3><div class="stats">${money(credits.reduce((s,x)=>s+Number(x.amount||0)-Number(x.used||0),0))}</div></div></div><h3 style="margin-top:16px">Referral Events</h3>${events.map(e=>`<div class="question"><b>${esc(e.referrer_name)}</b> referred ${esc(e.new_name)} • ${money(e.amount)} • ${esc(e.status)}<div class="muted">${esc(e.code)} • ${esc(e.created_at||'')}</div></div>`).join('')||'<p class="muted">No referral records.</p>'}<h3>Coupon Credits</h3>${credits.map(c=>`<div class="question">${esc(c.description)} • ${money(c.amount)} • Used ${money(c.used||0)} • Balance ${money(Number(c.amount||0)-Number(c.used||0))}</div>`).join('')||'<p class="muted">No coupon credits.</p>'}</div>`;}
function referralSettings(){if(!ownerOnly())return;modal('Referral Program Settings',`${formField('Reward per successful referral (INR)','ref_reward',MOCK.referral_reward_amount||500)}<label class="muted">Reward Eligibility</label><select class="input" id="f_ref_eligibility"><option>On valid account registration</option><option>After first paid invoice</option><option>Manual owner approval</option></select><button class="btn primary" onclick="saveReferralSettings()">Save Settings</button>`);}
function saveReferralSettings(){const n=Number($('f_ref_reward').value);if(!Number.isFinite(n)||n<0)return alert('Enter a valid reward amount.');MOCK.referral_reward_amount=n;MOCK.referral_eligibility=$('f_ref_eligibility').value;persistMock();closeModal();referrals();}
async function notifications(){const ns=MOCK.notifications||[];$('panel').innerHTML=`<div class="card"><div class="row"><h3 style="margin-right:auto">Notifications</h3><button class="btn primary" onclick="notificationForm()">+ Create Notification</button></div><p class="muted">Testing notifications are saved in this browser. Provider/email/SMS delivery is not connected in this build.</p>${ns.map(n=>{const p=n.payload||n;return `<div class="question"><div class="row"><b style="margin-right:auto">${esc(p.title||'Notification')}</b><span class="badge">${esc(p.status||'Unread')}</span></div><p>${esc(p.message||'')}</p><div class="row"><button class="btn" onclick="notificationForm(${n.id})">Edit</button><button class="btn" onclick="markNotificationRead(${n.id})">Mark Read</button><button class="btn" onclick="deleteNotification(${n.id})">Delete</button></div></div>`}).join('')||'<p class="muted">No notifications yet.</p>'}</div>`;}
function notificationForm(id){if(!ownerOnly()&&me.role!=='agency_admin')return;const n=(MOCK.notifications||[]).find(x=>String(x.id)===String(id));const p=n?.payload||n||{};modal(id?'Edit Notification':'Create Notification',`${formField('Title','notification_title',p.title||'')}${formField('Message','notification_message',p.message||'')}<label class="muted">Target</label><select class="input" id="f_notification_target"><option>All permitted users</option><option>Owner</option><option>Agency Admin</option><option>Customer</option></select><button class="btn primary" onclick="saveNotification(${id||'null'})">Save Notification</button>`);}
function saveNotification(id){const p={title:$('f_notification_title').value.trim(),message:$('f_notification_message').value.trim(),target:$('f_notification_target').value,status:'Unread',created_at:new Date().toISOString()};if(!p.title||!p.message)return alert('Title and message required.');if(id){const n=MOCK.notifications.find(x=>String(x.id)===String(id));if(n)n.payload=p;}else MOCK.notifications.unshift({id:Date.now(),payload:p});persistMock();closeModal();notifications();}
function markNotificationRead(id){const n=MOCK.notifications.find(x=>String(x.id)===String(id));if(n){(n.payload||n).status='Read';persistMock();notifications();}}
function deleteNotification(id){if(!confirm('Delete notification?'))return;MOCK.notifications=MOCK.notifications.filter(x=>String(x.id)!==String(id));persistMock();notifications();}

/* Chatbot configuration editor; live chat/AI requires provider credentials and website embed. */
async function chatbot(){const c=MOCK.chatbot_settings;$('panel').innerHTML=`<div class="card"><div class="row"><h3 style="margin-right:auto">Chatbot Manager</h3><span class="badge">${c.enabled?'Enabled':'Disabled'}</span></div><p class="muted">Configure the website chatbot. This testing build saves settings locally; live AI replies require a connected provider.</p><label class="muted">Status</label><select class="input" id="chatbot_enabled"><option value="false" ${!c.enabled?'selected':''}>Disabled</option><option value="true" ${c.enabled?'selected':''}>Enabled</option></select><label class="muted">Provider / Channel</label><select class="input" id="chatbot_provider">${['Website widget','WhatsApp','AI provider (credentials required)'].map(x=>`<option ${c.provider===x?'selected':''}>${x}</option>`).join('')}</select><label class="muted">Welcome Message</label><textarea class="input" id="chatbot_welcome">${esc(c.welcome_message||'')}</textarea><label class="muted">Fallback Message</label><textarea class="input" id="chatbot_fallback">${esc(c.fallback_message||'')}</textarea><button class="btn primary" onclick="saveChatbot()">Save Chatbot Settings</button><div class="question">Preview: ${esc(c.welcome_message||'Hello!')}</div></div>`;}
function saveChatbot(){MOCK.chatbot_settings={enabled:$('chatbot_enabled').value==='true',provider:$('chatbot_provider').value,welcome_message:$('chatbot_welcome').value,fallback_message:$('chatbot_fallback').value};persistMock();chatbot();}

/* SEO and domains now have editable status/settings. DNS/SSL publishing still needs real providers. */
async function seo(){const list=MOCK.seo||[];$('panel').innerHTML=`<div class="card"><div class="row"><h3 style="margin-right:auto">SEO Manager</h3><button class="btn primary" onclick="seoForm()">+ Add SEO Record</button></div><p class="muted">SEO metadata records are stored locally in this testing build. Search ranking is not guaranteed.</p><div class="grid">${list.map(x=>{const p=x.payload||x;return `<div class="card"><h3>${esc(p.title||p.page_url||'SEO Record')}</h3><p>${esc(p.description||'')}</p><p class="muted">${esc(p.page_url||'')} • ${esc(p.status||'Draft')}</p><div class="row"><button class="btn" onclick="seoForm(${x.id})">Edit</button><button class="btn" onclick="printSEO(${x.id})">Print / PDF</button><button class="btn" onclick="deleteSEO(${x.id})">Delete</button></div></div>`}).join('')||'<p class="muted">No SEO records.</p>'}</div></div>`;}
function seoForm(id){const x=(MOCK.seo||[]).find(y=>String(y.id)===String(id));const p=x?.payload||x||{};modal(id?'Edit SEO Record':'Add SEO Record',`${formField('Website / Page URL','seo_url',p.page_url||'https://example.com/page')}${formField('SEO Title','seo_title',p.title||'')}${formField('Meta Description','seo_description',p.description||'')}${formField('Keywords','seo_keywords',p.keywords||'')}${formField('Canonical URL','seo_canonical',p.canonical_url||'')}${formField('Image Alt Text','seo_alt',p.image_alt||'')}<label class="muted">Status</label><select class="input" id="f_seo_status"><option>Draft</option><option>Ready to publish</option></select><button class="btn primary" onclick="saveSEORecord(${id||'null'})">Save SEO</button>`);}
function saveSEORecord(id){const p={page_url:$('f_seo_url').value,title:$('f_seo_title').value,description:$('f_seo_description').value,keywords:$('f_seo_keywords').value,canonical_url:$('f_seo_canonical').value,image_alt:$('f_seo_alt').value,status:$('f_seo_status').value};if(!p.title&&!p.page_url)return alert('Page URL or SEO title required.');if(id){const x=MOCK.seo.find(y=>String(y.id)===String(id));if(x)x.payload=p;}else MOCK.seo.unshift({id:Date.now(),payload:p});persistMock();closeModal();seo();}
function printSEO(id){const x=MOCK.seo.find(y=>String(y.id)===String(id));if(x)printHTML('SEO RECORD',reportTable(['Field','Value'],Object.entries(x.payload||x)));}
function deleteSEO(id){if(!confirm('Delete SEO record?'))return;MOCK.seo=MOCK.seo.filter(x=>String(x.id)!==String(id));persistMock();seo();}
async function domains(){const list=MOCK.domains||[];$('panel').innerHTML=`<div class="card"><div class="row"><h3 style="margin-right:auto">Domains & Publishing</h3><button class="btn primary" onclick="domainForm()">+ Add Domain</button></div><p class="muted">Staging registry only. DNS changes, SSL provisioning and live hosting require real DNS/hosting provider integration.</p><div class="grid">${list.map(x=>{const p=x.payload||x;return `<div class="card"><div class="row"><h3 style="margin-right:auto">${esc(p.domain||'Domain')}</h3><span class="badge">${esc(p.status||'Pending DNS')}</span></div><p>Customer / Site: ${esc(p.customer_name||p.site_name||'Not linked')}</p><p class="muted">DNS: ${esc(p.dns_status||'Not verified')} • SSL: ${esc(p.ssl_status||'Not provisioned')} • Hosting: ${esc(p.hosting_status||'Not connected')}</p><p>${p.live_url?`<a href="${esc(p.live_url)}" target="_blank" rel="noopener">Open Live URL</a>`:''}</p><div class="row"><button class="btn" onclick="domainForm(${x.id})">Edit</button><button class="btn" onclick="toggleDomainStatus(${x.id})">Update Status</button><button class="btn" onclick="deleteDomain(${x.id})">Delete</button></div></div>`}).join('')||'<p class="muted">No domains yet.</p>'}</div></div>`;}
function domainForm(id){const x=(MOCK.domains||[]).find(y=>String(y.id)===String(id));const p=x?.payload||x||{};modal(id?'Edit Domain':'Add Domain',`${formField('Custom Domain / Subdomain','domain_name',p.domain||'example.com')}${formField('Linked Website / Funnel','domain_site',p.site_name||'')}${formField('Customer Account','domain_customer',p.customer_name||'')}${formField('Live URL (if deployed)','domain_live_url',p.live_url||'')}${formField('DNS Status','domain_dns',p.dns_status||'Pending')}${formField('SSL Status','domain_ssl',p.ssl_status||'Not provisioned')}${formField('Hosting Status','domain_hosting',p.hosting_status||'Not connected')}<button class="btn primary" onclick="saveDomainRecord(${id||'null'})">Save Domain</button>`);}
function saveDomainRecord(id){const domain=$('f_domain_name').value.trim().toLowerCase();if(!domain||!domain.includes('.'))return alert('Enter a valid domain or subdomain.');const p={domain,site_name:$('f_domain_site').value,customer_name:$('f_domain_customer').value,live_url:$('f_domain_live_url').value,dns_status:$('f_domain_dns').value||'Pending',ssl_status:$('f_domain_ssl').value||'Not provisioned',hosting_status:$('f_domain_hosting').value||'Not connected',status:'Configured (staging only)'};if(id){const x=MOCK.domains.find(y=>String(y.id)===String(id));if(x)x.payload=p;}else MOCK.domains.unshift({id:Date.now(),payload:p});persistMock();closeModal();domains();}
function toggleDomainStatus(id){const x=MOCK.domains.find(y=>String(y.id)===String(id));if(!x)return;const p=x.payload||x;p.dns_status=prompt('DNS status (e.g. Pending / Verified)',p.dns_status||'Pending')||p.dns_status;p.ssl_status=prompt('SSL status (e.g. Pending / Active)',p.ssl_status||'Not provisioned')||p.ssl_status;p.hosting_status=prompt('Hosting status',p.hosting_status||'Not connected')||p.hosting_status;persistMock();domains();}
function deleteDomain(id){if(!confirm('Delete domain record?'))return;MOCK.domains=MOCK.domains.filter(x=>String(x.id)!==String(id));persistMock();domains();}

/* Agency creation now includes the agency owner profile and a referral field. */
function newAgency(){if(!ownerOnly())return;const catOpts=(MOCK.pricing_categories||[]).map(c=>`<option>${esc(c.name)}</option>`).join('');modal('Create New Agency / Tenant',`<h4>Agency Details</h4>${formField('Legal / Registered Agency Name','agency_name','ABC Digital Marketing')}${formField('Portal Display Name','agency_display','ABC Digital Marketing')}${imageUploadField('Agency Logo','agency_logo')}${formField('Preferred Subdomain','agency_subdomain','abc-digital')}<label class="muted">Rental / Agency Plan</label><select class="input" id="f_plan_category">${(MOCK.pricing_categories||[]).filter(c=>/tenant|agency|rented/i.test(c.name)).map(c=>`<option>${esc(c.name)}</option>`).join('')}</select><label class="muted">Specific Plan</label><select class="input" id="f_plan">${(MOCK.pricing_categories||[]).filter(c=>/tenant|agency|rented/i.test(c.name)).flatMap(c=>(c.plans||[]).map(p=>`<option value="${esc(p.name)}">${esc(p.name)} — ${money(p.price)} / ${esc(p.cycle)}</option>`)).join('')||'<option>Agency Pro</option>'}</select><label class="muted">Status</label><select class="input" id="f_status"><option>Active</option><option>Suspended</option></select><h4>Agency Owner Profile</h4>${formField('Owner Full Name','admin_name','Agency Owner')}${formField('Owner Email / Login ID','admin_email','owner@agency.com')}<label class="muted">Owner Mobile Number</label><input class="input" id="f_admin_phone" inputmode="numeric" maxlength="10" placeholder="10-digit mobile number">${formField('Owner Address','admin_address','Address')}${stateCityInputs('admin_state','admin_city')}${formField('Business Category','agency_category','Digital Marketing')}<label class="muted">Owner Password</label><div class="row"><input class="input" id="f_admin_password" type="password" minlength="8" placeholder="Minimum 8 characters"><button class="btn" type="button" onclick="togglePasswordVisibility('f_admin_password')">Show / Hide</button></div><h4>Referral (Optional)</h4>${formField('Referral Code','agency_referral_code','Existing customer / agency referral code')}<p class="muted">Referral reward goes to the existing referrer, not this new agency.</p><button class="btn primary" onclick="saveAgencyV77()">Create Agency + Owner Login</button>`);}
function togglePasswordVisibility(id){const x=$(id);if(x)x.type=x.type==='password'?'text':'password';}
function saveAgencyV77(){if(!ownerOnly())return;const name=$('f_agency_name').value.trim(),display=$('f_agency_display').value.trim()||name,email=$('f_admin_email').value.trim().toLowerCase(),phone=$('f_admin_phone').value.trim(),password=$('f_admin_password').value,ref=$('f_agency_referral_code').value.trim();if(!name||!email||!password)return alert('Agency name, Owner email and password are required.');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return alert('Enter a valid email.');if(password.length<8)return alert('Password must be at least 8 characters.');if(MOCK.users.some(u=>String(u.email||'').toLowerCase()===email))return alert('This email is already registered.');if(phone&&normalizedPhone(phone).length!==10)return alert('Enter a valid 10-digit owner mobile number.');if(phone&&MOCK.users.some(u=>normalizedPhone(u.phone)===normalizedPhone(phone)))return alert('This mobile number is already registered.');const id=Date.now();const cat=MOCK.pricing_categories.find(c=>c.name===$('f_plan_category').value);const plan=$('f_plan').value||'Agency Pro';const a={id,name,brand_name:display,display_name:display,logo_url:$('f_agency_logo')?.dataset?.data||'',subdomain:$('f_agency_subdomain').value.trim().toLowerCase(),plan,plan_category:cat?.name||'Tenant / Agency Plans',status:$('f_status').value,owner_name:$('f_admin_name').value.trim(),owner_email:email,owner_phone:phone,address:$('f_admin_address').value,city:$('f_admin_city').value,state:$('f_admin_state').value,industry:$('f_agency_category').value,referral_code:referralCode('agency',id)};const u={id:id+1,name:a.owner_name,email,phone,role:'agency_owner',agency_id:id,status:'Active',permissions:['*'],password,referral_code:referralCode('agency',id)};MOCK.agencies.unshift(a);MOCK.users.push(u);if(ref)try{issueReferralReward(ref,'agency',id,display);}catch(e){MOCK.agencies=MOCK.agencies.filter(x=>x.id!==id);MOCK.users=MOCK.users.filter(x=>x.id!==id+1);return alert(e.message);}persistMock();closeModal();alert('Agency and Owner Profile created. Login email: '+email);agencies();}

/* New customer registration: referral code and strict unique email/mobile check. */
function newCustomer(){modal('Add New Customer',customerProfileFields()+`<div class="card" style="margin-top:10px">${formField('Plan / Service','plan','Meta Ads / Google Ads / Website Design')}<label class="muted">Customer Login Password</label><div class="row"><input class="input" id="f_login_password" type="password" minlength="8" autocomplete="new-password" placeholder="Minimum 8 characters"><button class="btn" type="button" onclick="togglePasswordVisibility('f_login_password')">Show / Hide</button></div><h4>Referral (Optional)</h4>${formField('Referral Code','customer_referral_code','Existing customer / agency code')}<div class="muted">Referral benefit is credited to the existing referrer only after a valid unique registration.</div></div><button class="btn primary" onclick="saveCustomerV77()">Create Customer + Login</button>`);}
function saveCustomerV77(){const name=$('f_name').value.trim(),business=$('f_business_name').value.trim(),email=$('f_email').value.trim().toLowerCase(),code=$('f_country_code').value.trim(),digits=$('f_phone').value.replace(/\D/g,''),phone=code+digits,plan=$('f_plan').value.trim(),password=$('f_login_password').value,ref=$('f_customer_referral_code').value.trim();if(!name||!business||!email||!digits||!plan||!password)return alert('Please fill the required customer fields.');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return alert('Enter a valid email.');if(!/^\+\d{1,4}$/.test(code)||!/^\d{10}$/.test(digits))return alert('Enter country code and exactly 10 mobile digits.');if(password.length<8)return alert('Password must be at least 8 characters.');if(findDuplicateCustomer(email,phone)||MOCK.users.some(u=>String(u.email||'').toLowerCase()===email||(normalizedPhone(u.phone)&&normalizedPhone(u.phone)===normalizedPhone(phone))))return alert('Customer not created: this email or mobile number is already registered. Edit the existing account instead.');const id=Date.now();const c={id,name,business_name:business,email,phone,plan,industry:$('f_industry').value,address:$('f_address').value,city:$('f_city').value,state:$('f_state').value,pincode:$('f_pincode').value,website_url:$('f_website_url').value,instagram_url:$('f_instagram_url').value,facebook_url:$('f_facebook_url').value,logo_url:$('f_logo_url').value,owner_photo_url:$('f_owner_photo_url').value,billing_name:$('f_billing_name').value,pan:$('f_pan').value,gstin:$('f_gstin').value,gst_status:$('f_gst_status').value,billing_address:$('f_billing_address').value,notes:$('f_notes').value,agency_id:me.agency_id||1,status:'Active',referral_code:referralCode('customer',id)};MOCK.customers.unshift(c);MOCK.users.push({id:id+1,name,email,phone,role:'customer',agency_id:me.agency_id||1,customer_id:id,status:'Active',permissions:['dashboard','templates','crm','pipelines','forms','funnels','campaigns','payments','referrals','notifications','reports'],password});if(ref)try{issueReferralReward(ref,'customer',id,business);}catch(e){MOCK.customers=MOCK.customers.filter(x=>x.id!==id);MOCK.users=MOCK.users.filter(x=>x.id!==id+1);return alert(e.message);}persistMock();closeModal();alert('Customer created successfully. Referral reward (if any) is credited to the existing referrer.');customers();}

/* Owner permission controls are expanded to every module, including accounting. */
const ACCESS_MODULES_V77=['dashboard','customers','pipelines','crm','lead_automation','forms','funnels','sales','operations','inbox','calendar','tasks','campaigns','meta_ads','google_ads','whatsapp','websites','templates','payments','expenses','ledger','reports','domains','seo','referrals','chatbot','notifications','agencies','plans_pricing','settings','audit'];
function buildNav(){const role=me.role||me.user?.role;const groups=[['MAIN',[['dashboard','🏠 Dashboard'],['customers','👥 Customers'],['pipelines','📊 Pipelines']]],['LEADS & CRM',[['crm','🎯 Lead Management'],['lead_automation','⚡ Lead Automation'],['forms','📝 Forms'],['funnels','🔗 Funnels']]],['SALES & OPERATIONS',[['sales','💼 Sales'],['operations','⚙ Operations'],['inbox','📥 Inbox'],['calendar','📅 Calendar'],['tasks','✅ Tasks']]],['MARKETING',[['campaigns','📣 Campaigns'],['meta_ads','📈 Meta Ads'],['google_ads','📊 Google Ads'],['whatsapp','💬 WhatsApp'],['websites','🌐 Websites'],['templates','📚 Templates']]],['FINANCE & REPORTS',[['payments','💳 Finance / Billing'],['expenses','🧾 Expenses'],['ledger','📒 Ledger'],['reports','📊 Reports']]],['TOOLS',[['domains','🔗 Domains'],['seo','🔎 SEO'],['referrals','🤝 Referrals / Reviews'],['chatbot','🤖 Chatbot'],['notifications','🔔 Notifications']]],['AGENCY MANAGEMENT',[['agencies','🏢 Agencies / Tenants']]],['BUSINESS SETTINGS',[['plans_pricing','🏷 Plans & Pricing']]],['ADMIN',[['settings','⚙ Settings'],['audit','🛡 Audit Logs'],['training_reset','🧪 Reset Training Data']]]];$('nav').innerHTML=groups.map(g=>{const items=g[1].filter(x=>{if(['agencies','plans_pricing','expenses','ledger'].includes(x[0])&&role!=='platform_owner'&&role!=='agency_admin'&&role!=='agency_owner')return false;if(x[0]==='plans_pricing'&&role!=='platform_owner')return false;if(x[0]==='training_reset'&&!TRAINING_MODE)return false;return me.permissions.includes('*')||me.permissions.includes(x[0])||((['settings','audit'].includes(x[0]))&&['platform_owner','agency_owner','agency_admin'].includes(role))});return items.length?`<div class="nav-group"><div class="nav-label">${g[0]}</div>${items.map(x=>`<button class="nav-btn" data-k="${x[0]}" onclick="openPage('${x[0]}')">${x[1]}</button>`).join('')}</div>`:''}).join('');}
async function openPage(k){setActive(k);const p=$('panel');p.innerHTML='<div class="card">Loading…</div>';try{if(k==='dashboard')return dashboard();if(k==='customers')return customers();if(k==='templates')return templates();if(k==='crm')return crm();if(k==='pipelines')return pipelines();if(k==='forms')return forms();if(k==='funnels')return funnels();if(k==='campaigns')return recordsPage('Campaigns','/campaigns',true);if(k==='lead_automation')return moduleManager('Lead Automation','lead_automation',moduleFields('lead_automation'));if(k==='sales')return moduleManager('Sales','sales',moduleFields('sales'));if(k==='operations')return moduleManager('Operations','operations',moduleFields('operations'));if(k==='inbox')return moduleManager('Inbox','inbox',moduleFields('inbox'));if(k==='calendar')return moduleManager('Calendar','calendar',moduleFields('calendar'));if(k==='tasks')return moduleManager('Tasks','tasks',moduleFields('tasks'));if(k==='meta_ads')return meta();if(k==='google_ads')return googleAds();if(k==='whatsapp')return whatsapp();if(k==='websites')return websites();if(k==='domains')return domains();if(k==='seo')return seo();if(k==='payments')return billing();if(k==='expenses')return expenses();if(k==='ledger')return ledgerPage();if(k==='referrals')return referrals();if(k==='chatbot')return chatbot();if(k==='notifications')return notifications();if(k==='agencies')return agencies();if(k==='plans_pricing')return plansPricing();if(k==='settings')return settings();if(k==='reports')return reports();if(k==='audit')return audit();if(k==='training_reset')return trainingResetPage();}catch(e){p.innerHTML=`<div class="card danger"><b>Could not load ${esc(k)}</b><p>${esc(e.message)}</p><button class="btn" onclick="openPage('${k}')">Retry</button></div>`}}
async function ledgerPage(){const rows=ledgerRows(),accounts=[...allCustomers().map(c=>({type:'customer',id:c.id,name:accountName(c)})),...(MOCK.agencies||[]).map(a=>({type:'agency',id:a.id,name:accountName(a)}))];$('panel').innerHTML=`<div class="card"><div class="row"><h3 style="margin-right:auto">Customer / Agency Ledger</h3><button class="btn" onclick="printLedger()">Print All / Save PDF</button></div><label class="muted">Filter by Account</label><select class="input" id="ledger_account_filter" onchange="renderLedgerAccount()"><option value="all">All Accounts</option>${accounts.map(a=>`<option value="${a.type}:${a.id}">${esc(a.type==='agency'?'Agency: ':'Customer: ')}${esc(a.name)}</option>`).join('')}</select><p class="muted">Ledger entries are derived from invoices, payments and referral coupon credits. A formal accounting review is recommended before production.</p><div id="ledger_table"></div></div>`;renderLedgerAccount();}
function renderLedgerAccount(){let rows=ledgerRows();const v=$('ledger_account_filter')?.value||'all';let type=null,id=null;if(v!=='all'){[type,id]=v.split(':');rows=rows.filter(r=>r.account_type===type&&String(r.customer_id)===String(id));}let bal=0;const t=rows.map(r=>{bal+=r.debit-r.credit;return [formatDateIN(r.date),r.account,r.ref,r.type,money(r.debit),money(r.credit),money(bal)];});const el=$('ledger_table');if(el)el.innerHTML=reportTable(['Date','Account','Reference','Type','Debit','Credit','Running Balance'],t)+`<div class="total"><b>Closing Balance: ${money(bal)}</b> <button class="btn mini" onclick="printLedger('${type||''}','${id||''}')">Print Selected / Save PDF</button></div>`;}
function printPayment(id){const p=MOCK.payments.find(x=>String(x.id)===String(id));if(!p)return;const i=MOCK.invoices.find(x=>String(x.id)===String(p.invoice_id));printHTML('PAYMENT RECEIPT',`<p><b>Receipt No:</b> ${esc('RCPT-'+p.id)}<br><b>Payment Date:</b> ${esc(p.paid_at||'')}<br><b>Customer:</b> ${esc(p.customer_name||accountName(p.account_type==='agency'?(MOCK.agencies||[]).find(c=>String(c.id)===String(p.account_id||p.customer_id)):allCustomers().find(c=>String(c.id)===String(p.customer_id))))}<br><b>Invoice:</b> ${esc(p.invoice_no||'—')}</p>${reportTable(['Amount','Mode','Reference','Status'],[[money(p.amount),p.payment_mode,p.transaction_ref,p.status]])}<p class="total"><b>Amount Received: ${money(p.amount)}</b><br>Invoice Balance: ${money(i?Number(i.total??i.amount)-Number(i.paid_amount||0):0)}</p>`);}

async function customers(){const d=await api('/customers');$('panel').innerHTML=`<div class="card"><div class="row"><h3 style="margin-right:auto">Customers</h3>${me.role!=='customer'?'<button class="btn primary" onclick="newCustomer()">+ Add Customer</button>':''}</div><p class="muted">Unique email and mobile; referral coupon is credited to the existing referrer only.</p><div class="grid">${d.map(x=>`<div class="card"><div class="row"><h3 style="margin-right:auto">${esc(accountName(x))}</h3><span class="badge">${esc(x.status||'Active')}</span></div><p>${esc(x.name)} • ${esc(x.email)} • ${esc(x.phone||'')}</p><p>Business Category: <b>${esc(x.industry||'—')}</b> • Plan: <b>${esc(x.plan||'Custom')}</b></p><div class="question"><b>Referral Code:</b> ${esc(x.referral_code||referralCode('customer',x.id))}<br><b>Coupon Balance:</b> ${money(couponBalance('customer',x.id))}<div class="row" style="margin-top:8px"><button class="btn mini" onclick="navigator.clipboard?.writeText('${esc(x.referral_code||referralCode('customer',x.id))}').then(()=>alert('Referral code copied')).catch(()=>alert('${esc(x.referral_code||referralCode('customer',x.id))}'))">Copy Referral Code</button></div></div><div class="row"><button class="btn" onclick="editCustomer(${x.id})">Edit Profile</button><button class="btn" onclick="toggleCustomer(${x.id},'${x.status==='Active'?'Suspended':'Active'}')">${x.status==='Active'?'Suspend':'Activate'}</button></div></div>`).join('')||'<div class="card">No customers</div>'}</div></div>`;}
async function agencies(){if(!ownerOnly())return;const d=MOCK.agencies||[];$('panel').innerHTML=`<div class="card"><div class="row"><h3 style="margin-right:auto">Agency / Tenant Management</h3><button class="btn primary" onclick="newAgency()">+ Add Agency</button></div><p class="muted">Manage agency workspace and first owner profile. Referral reward goes to the existing referrer.</p><div class="grid">${d.map(a=>`<div class="card"><div class="row"><h3 style="margin-right:auto">${esc(a.display_name||a.brand_name||a.name)}</h3><span class="badge">${esc(a.status||'Active')}</span></div><p>Registered: ${esc(a.name)}<br>Owner: ${esc(a.owner_name||'—')} • ${esc(a.owner_email||'—')}<br>Mobile: ${esc(a.owner_phone||'—')}</p><p>Plan: <b>${esc(a.plan||'Agency Pro')}</b> • ${esc(a.plan_category||'')}</p><p class="muted">Tenant ID: ${a.id} • Referral Code: ${esc(a.referral_code||referralCode('agency',a.id))} • Coupon: ${money(couponBalance('agency',a.id))}</p><div class="row"><button class="btn primary" onclick="editAgencyV77(${a.id})">Manage / Edit Profile</button></div></div>`).join('')||'<div class="card">No agencies yet.</div>'}</div></div>`;}
function editAgencyV77(id){if(!ownerOnly())return;const a=MOCK.agencies.find(x=>String(x.id)===String(id));if(!a)return;modal('Manage Agency & Owner Profile',`${formField('Legal / Registered Agency Name','edit_agency_name',a.name||'')}${formField('Portal Display Name','edit_agency_display',a.display_name||a.brand_name||a.name||'')}${formField('Owner Full Name','edit_agency_owner',a.owner_name||'')}${formField('Owner Email','edit_agency_email',a.owner_email||'')}${formField('Owner Mobile','edit_agency_phone',a.owner_phone||'')}${formField('Address','edit_agency_address',a.address||'')}${formField('City','edit_agency_city',a.city||'')}${formField('State','edit_agency_state',a.state||'')}${formField('Business Category','edit_agency_category',a.industry||'')}${formField('Subdomain','edit_agency_subdomain',a.subdomain||'')}<label class="muted">Status</label><select class="input" id="f_edit_agency_status"><option ${a.status==='Active'?'selected':''}>Active</option><option ${a.status==='Suspended'?'selected':''}>Suspended</option></select><button class="btn primary" onclick="saveAgencyProfile(${id})">Save Agency + Owner Profile</button>`);}
function saveAgencyProfile(id){if(!ownerOnly())return;const a=MOCK.agencies.find(x=>String(x.id)===String(id));if(!a)return;const email=$('f_edit_agency_email').value.trim().toLowerCase(),phone=$('f_edit_agency_phone').value.trim();if(!email||!/^\S+@\S+\.\S+$/.test(email))return alert('Valid owner email required.');if(MOCK.users.some(u=>String(u.email||'').toLowerCase()===email&&String(u.id)!==String(Number(id)+1)))return alert('This email is already registered.');if(phone&&normalizedPhone(phone).length!==10)return alert('Owner mobile must be 10 digits.');Object.assign(a,{name:$('f_edit_agency_name').value.trim(),display_name:$('f_edit_agency_display').value.trim(),brand_name:$('f_edit_agency_display').value.trim(),owner_name:$('f_edit_agency_owner').value.trim(),owner_email:email,owner_phone:phone,address:$('f_edit_agency_address').value,city:$('f_edit_agency_city').value,state:$('f_edit_agency_state').value,industry:$('f_edit_agency_category').value,subdomain:$('f_edit_agency_subdomain').value,status:$('f_edit_agency_status').value});const u=MOCK.users.find(x=>Number(x.id)===Number(id)+1);if(u){u.name=a.owner_name;u.email=email;u.phone=phone;}persistMock();closeModal();agencies();}

/* Pipeline stage history and comments. */
async function moveLeadStage(id,stage){try{const rec=(MOCK.crm||[]).find(x=>String(x.id)===String(id));if(OFFLINE&&rec){const q=rec.payload||rec,old=q.stage||'New';q.stage_history=Array.isArray(q.stage_history)?q.stage_history:[];q.stage_history.unshift({from:old,to:stage,by:me?.name||me?.email||'User',at:new Date().toISOString()});q.stage=stage;persistMock();return crm();}await api('/crm/leads/'+id+'/stage',{method:'PATCH',body:JSON.stringify({stage})});crm();}catch(e){alert(e.message)}}
async function showLeadDetails(id){const d=await api('/crm');const x=d.find(r=>Number(r.id)===Number(id));if(!x)return alert('Lead not found');const q=x.payload||x;const history=q.stage_history||[],comments=q.comments||[];modal('Lead Details',`<div class="card"><h3>${esc(q.name||'Unnamed Lead')}</h3><p><b>Mobile:</b> ${esc(q.phone||'—')}<br><b>Email:</b> ${esc(q.email||'—')}<br><b>Source:</b> ${esc(q.source||'Manual')}<br><b>Stage:</b> ${esc(q.stage||'New')}<br><b>Customer:</b> ${esc(q.customer_id||'—')}<br><b>Pipeline:</b> ${esc(q.pipeline_id||'—')}</p><h4>Lead Data</h4><div class="json">${esc(JSON.stringify(q.answers||q.fields||{},null,2))}</div><h4>Stage History</h4>${history.map(h=>`<div class="question">${esc(h.from)} → <b>${esc(h.to)}</b><div class="muted">${esc(h.by)} • ${esc(h.at)}</div></div>`).join('')||'<p class="muted">No stage changes recorded yet.</p>'}<h4>Comments / Notes</h4>${comments.map(c=>`<div class="question">${esc(c.text)}<div class="muted">${esc(c.by)} • ${esc(c.at)}</div></div>`).join('')||'<p class="muted">No comments yet.</p>'}<textarea class="input" id="lead_comment_text" placeholder="Add comment or follow-up note"></textarea><button class="btn primary" onclick="saveLeadComment(${id})">Add Comment</button></div><button class="btn" onclick="closeModal()">Close</button>`);}
function saveLeadComment(id){const rec=(MOCK.crm||[]).find(x=>String(x.id)===String(id)),textv=$('lead_comment_text')?.value.trim();if(!rec||!textv)return alert('Enter a comment.');const q=rec.payload||rec;q.comments=Array.isArray(q.comments)?q.comments:[];q.comments.unshift({text:textv,by:me?.name||me?.email||'User',at:new Date().toISOString()});persistMock();showLeadDetails(id);}

/* Form builder includes an image upload field for the form background. */
async function newForm(){formQuestions=[{label:'Full Name',type:'text',required:true,options:[]},{label:'Mobile Number',type:'tel',required:true,options:[]}];let cs=[],ps=[];if(me.role!=='customer'){cs=await api('/customers');ps=await api('/pipelines')}const cOpts=cs.map(c=>`<option value="${c.id}">${esc(c.business_name||c.name)}</option>`).join(''),pOpts=ps.map(x=>`<option value="${x.id}">${esc(x.name)} — Customer #${x.customer_id}</option>`).join('');modal('New Form',`${me.role!=='customer'?`<label class="muted">Customer</label><select class="input" id="f_customer_id">${cOpts}</select>`:''}<label class="muted">Pipeline</label><select class="input" id="f_pipeline_id"><option value="">Auto-create / select later</option>${pOpts}</select>${formField('Form name','name','Meta Ads Enquiry Form')}${imageUploadField('Form Background Image (optional)','form_background')}<div class="row" style="margin:8px 0"><h3 style="margin-right:auto">Questions</h3><button class="btn dark mini" onclick="addQuestion()">+ Add Question</button></div><div id="questionEditor"></div><div class="card"><b>CRM mapping</b><div class="muted">Name/Mobile/Email answers can be mapped to CRM automatically.</div></div><button class="btn primary" onclick="saveForm()">Create Form</button>`);renderQuestions();}
async function saveForm(){try{if(!$('f_name').value.trim())return alert('Form name required');if(!formQuestions.length)return alert('Add at least one question');await api('/forms',{method:'POST',body:JSON.stringify({name:$('f_name').value,background_image:$('f_form_background')?.value||'',customer_id:me.role==='customer'?undefined:Number($('f_customer_id')?.value||0)||undefined,pipeline_id:Number($('f_pipeline_id')?.value||0)||undefined,fields:formQuestions.map(q=>q.label),questions:formQuestions,thank_you:'Thank you! Our team will contact you.',crm_mapping:{name:'Full Name',phone:'Mobile Number',email:'Email'}})});closeModal();forms();}catch(e){alert(e.message)}}

/* Owner/admin password reset controls. */
function editUserAccess(id){const u=CURRENT_SETTINGS_USERS.find(x=>Number(x.id)===Number(id));if(!u)return;if(me.role==='platform_owner')return alert('Platform Owner access is global and is not managed as agency team permissions.');if(u.role==='agency_owner')return alert('Agency Owner account cannot be modified by another team member.');if(me.role==='agency_admin'&&u.role!=='agency_staff')return alert('Admin can manage Staff permissions only.');const boxes=ACCESS_MODULES.map(k=>`<label class="row" style="margin:5px 0"><input type="checkbox" style="width:auto" data-perm="${k}" ${u.permissions?.includes('*')||u.permissions?.includes(k)?'checked':''}> ${k.replace(/_/g,' ')}</label>`).join('');modal('Manage Access – '+esc(u.name),`<div class="muted">${esc(u.email)} • ${esc(u.role)}</div><div class="card" style="margin-top:10px">${boxes}</div><div class="row"><button class="btn primary" onclick="saveUserAccess(${id})">Save Access</button><button class="btn" onclick="resetUserPassword(${id})">Reset Password</button></div>`);}
function resetUserPassword(id){if(!['platform_owner','agency_admin'].includes(me?.role))return alert('Access denied.');modal('Reset User Password',`<label class="muted">New Password (minimum 8 characters)</label><input class="input" id="reset_user_password" type="password" minlength="8"><button class="btn primary" onclick="saveResetUserPassword(${id})">Save New Password</button>`);}
async function saveResetUserPassword(id){const password=$('reset_user_password').value;if(password.length<8)return alert('Password must be at least 8 characters.');try{if(OFFLINE){const u=(MOCK.users||[]).find(x=>Number(x.id)===Number(id));if(!u)return alert('User not found.');u.password=password;persistMock();closeModal();alert('Password reset in this browser testing build.');return;}await api('/users/'+id,{method:'PATCH',body:JSON.stringify({password})});closeModal();alert('Password reset request saved.');}catch(e){alert(e.message)}}

/* Multi-page website defaults: do not force every site into a single page. */
async function websites(){const raw=await api('/websites');const d=raw.filter(x=>{const p=x.payload||{};return p.multi_page===true||p.single_page!==true||p.template_id||!Array.isArray(p.pages)||p.pages.length>1;});$('panel').innerHTML=`<div class="card"><div class="row"><div style="margin-right:auto"><h3>🌐 Website Builder</h3><p class="muted">Create multi-page business websites with editable pages, theme, language, forms and SEO metadata.</p></div><button class="btn dark" onclick="aiBuild('website')">✨ Create with AI</button><button class="btn primary" onclick="newSite()">+ New Website</button></div></div>${templateShortcut('website')}${templateShortcut('landing')}<div class="card"><h3>Websites</h3><div class="grid">${d.map(x=>{const p=x.payload||{};return `<div class="card"><h3>${esc(p.name||'Website')}</h3><div class="muted">${esc(p.status||'Draft')} • ${esc(p.slug||'')}</div><p>${p.single_page?'Single page (legacy)':'Multi-page website'} • ${(p.pages||[]).length||6} pages</p><div class="muted">Pages: ${esc((p.pages||[]).join(' • ')||'Home • About • Services • Contact')}</div>${p.published_url?`<div class="muted">🔗 ${esc(p.published_url)}</div>`:''}<div class="row"><button class="btn primary" onclick="openTemplateEditor(${x.id},'website')">Open / Edit Website</button><button class="btn" onclick="publishPublic('websites',${x.id})">${p.published_url?'Copy Link':'Publish & Get Link'}</button></div></div>`}).join('')||'<p class="muted">No websites yet.</p>'}</div></div>`;}
async function newSite(){let cs=[];if(me.role!=='customer')cs=await api('/customers');const opts=cs.map(c=>`<option value="${c.id}">${esc(c.business_name||c.name)}</option>`).join('');modal('New Multi-Page Website',(me.role!=='customer'?`<label class="muted">Customer</label><select class="input" id="f_customer_id">${opts}</select>`:'')+formField('Website name','name')+formField('SEO description','desc')+`<label class="muted">Pages (comma separated)</label><input class="input" id="f_site_pages" value="Home, About, Services, Portfolio, Testimonials, Contact"><button class="btn primary" onclick="saveSite()">Create Multi-Page Website</button>`);}
async function saveSite(){try{const name=$('f_name').value.trim();if(!name)return alert('Website name required.');const pages=($('f_site_pages')?.value||'Home, About, Services, Portfolio, Testimonials, Contact').split(',').map(x=>x.trim()).filter(Boolean);if(pages.length<2)return alert('A multi-page website must have at least two pages.');await api('/websites',{method:'POST',body:JSON.stringify({name,customer_id:me.role==='customer'?undefined:Number($('f_customer_id')?.value||0)||undefined,single_page:false,multi_page:true,pages,slug:name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/,''),status:'Draft',seo:{title:name,description:$('f_desc').value},page_content:Object.fromEntries(pages.map(p=>[p,{title:p,sections:['Hero','Content','Call to Action','Contact Form']}]))})});closeModal();websites();}catch(e){alert(e.message)}}

/* State and City are dropdowns in customer and agency-owner profiles. */
const V77_STATES=['Andhra Pradesh','Arunachal Pradesh','Assam','Bihar','Chhattisgarh','Goa','Gujarat','Haryana','Himachal Pradesh','Jharkhand','Karnataka','Kerala','Madhya Pradesh','Maharashtra','Manipur','Meghalaya','Mizoram','Nagaland','Odisha','Punjab','Rajasthan','Sikkim','Tamil Nadu','Telangana','Tripura','Uttar Pradesh','Uttarakhand','West Bengal','Delhi','Jammu and Kashmir','Ladakh','Puducherry'];
const V77_CITIES=['Mumbai','Thane','Navi Mumbai','Bhandup','Pune','Nagpur','Nashik','Aurangabad','Kolhapur','Solapur','Delhi','Bengaluru','Chennai','Hyderabad','Ahmedabad','Surat','Vadodara','Jaipur','Kolkata','Bhubaneswar','Patna','Lucknow','Indore','Bhopal','Panaji','Other'];
function stateCityInputs(stateId='state',cityId='city',stateVal='',cityVal=''){return `<label class="muted">State</label><select class="input" id="f_${stateId}"><option value="">Select State</option>${V77_STATES.map(x=>`<option ${x===stateVal?'selected':''}>${esc(x)}</option>`).join('')}</select><label class="muted">City</label><select class="input" id="f_${cityId}"><option value="">Select City</option>${V77_CITIES.map(x=>`<option ${x===cityVal?'selected':''}>${esc(x)}</option>`).join('')}${cityVal&&!V77_CITIES.includes(cityVal)?`<option selected>${esc(cityVal)}</option>`:''}</select>`;}
function customerProfileFields(prefix=''){return `<div class="card" style="margin-top:10px"><h4>Business Details</h4>${formField('Business Name','business_name')}${formField('Contact Person Name','name')}${formField('Email / Login ID','email','name@example.com')}<label class="muted">Mobile Number</label><div class="row" style="gap:8px;flex-wrap:nowrap"><input class="input" id="f_country_code" value="+91" maxlength="5" style="flex:0 0 72px"><input class="input" id="f_phone" placeholder="10-digit mobile number" maxlength="10" inputmode="numeric" style="flex:1;min-width:0" oninput="this.value=this.value.replace(/\D/g,'').slice(0,10)"></div>${formField('Business Category / Industry','industry','e.g. Real Estate')}${formField('Business Address','address')}${stateCityInputs('state','city')}${formField('PIN Code','pincode')}${formField('Website URL (optional)','website_url','https://')}${formField('Instagram URL (optional)','instagram_url','https://instagram.com/...')}${formField('Facebook URL (optional)','facebook_url','https://facebook.com/...')}${imageUploadField('Business Logo','logo_url')} ${imageUploadField('Owner / Profile Photo','owner_photo_url')}</div><div class="card" style="margin-top:10px"><h4>Billing / GST</h4>${formField('Billing Name / Legal Business Name','billing_name')}${formField('PAN (optional)','pan')}${formField('GSTIN (optional)','gstin')}<label class="muted">GST Status</label><select class="input" id="f_gst_status"><option>Not Registered</option><option>GST Registered</option><option>Composition / Other</option></select>${formField('Billing Address','billing_address')}${formField('Internal Notes','notes')}</div>`;}
async function editCustomer(id){const c=(await api('/customers')).find(x=>Number(x.id)===Number(id));if(!c)return;modal('Edit Customer Profile',customerProfileFields()+`<button class="btn primary" onclick="saveCustomerEdit(${id})">Save Customer Profile</button>`);['business_name','name','email','industry','address','pincode','website_url','instagram_url','facebook_url','logo_url','owner_photo_url','billing_name','pan','gstin','billing_address','notes'].forEach(k=>{if($('f_'+k))$('f_'+k).value=c[k]||''});$('f_country_code').value=(String(c.phone||'').match(/^\+\d{1,4}/)||['+91'])[0];$('f_phone').value=String(c.phone||'').replace(/^\+\d{1,4}[- ]?/,'');if($('f_state')&&c.state&&!V77_STATES.includes(c.state))$('f_state').add(new Option(c.state,c.state));$('f_state').value=c.state||'';if($('f_city')&&c.city&&!V77_CITIES.includes(c.city))$('f_city').add(new Option(c.city,c.city));$('f_city').value=c.city||'';$('f_gst_status').value=c.gst_status||'Not Registered';}
async function saveCustomerEdit(id){const code=$('f_country_code').value.trim(),digits=$('f_phone').value.replace(/\D/g,''),email=$('f_email').value.trim().toLowerCase(),phone=code+digits;if(!/^\+\d{1,4}$/.test(code)||!/^\d{10}$/.test(digits))return alert('Enter a valid country code and 10-digit mobile number.');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return alert('Enter a valid email.');if(findDuplicateCustomer(email,phone,id))return alert('This email or mobile belongs to another customer. Duplicate update blocked.');const linkedUser=MOCK.users.find(u=>String(u.customer_id)===String(id));if(MOCK.users.some(u=>String(u.email||'').toLowerCase()===email&&String(u.id)!==String(linkedUser?.id||'')))return alert('This email is already registered to another portal user.');if(MOCK.users.some(u=>normalizedPhone(u.phone)&&normalizedPhone(u.phone)===normalizedPhone(phone)&&String(u.id)!==String(linkedUser?.id||'')))return alert('This mobile number is already registered to another portal user.');const body={name:$('f_name').value.trim(),business_name:$('f_business_name').value.trim(),email,phone,industry:$('f_industry').value,address:$('f_address').value,city:$('f_city').value,state:$('f_state').value,pincode:$('f_pincode').value,website_url:$('f_website_url').value,instagram_url:$('f_instagram_url').value,facebook_url:$('f_facebook_url').value,logo_url:$('f_logo_url').value,owner_photo_url:$('f_owner_photo_url').value,billing_name:$('f_billing_name').value,pan:$('f_pan').value,gstin:$('f_gstin').value,gst_status:$('f_gst_status').value,billing_address:$('f_billing_address').value,notes:$('f_notes').value};try{if(OFFLINE){const c=MOCK.customers.find(x=>String(x.id)===String(id));if(!c)return alert('Customer not found.');Object.assign(c,body);if(linkedUser){linkedUser.name=body.name;linkedUser.email=body.email;linkedUser.phone=body.phone;}persistMock();closeModal();customers();return;}await api('/customers/'+id,{method:'PATCH',body:JSON.stringify(body)});closeModal();customers();}catch(e){alert(e.message)}}

